import { api, AdminApiError, localPreview } from './api.js?v=10';
import { badge, button, dateTime, empty, escapeHtml, field, icon, mediaPicker, metric, modal, money, pageHeader, panel, safeUrl, selectField, switchField } from './components.js?v=12';

const root = document.getElementById('admin-app');
const routes = ['overview','operations','intelligence','support','users','games','payments','compliance','banners','vip','appearance','social','settings','team','audit'];
const routeInfo = {
  overview:['Operations','Overview'], operations:['Reliability','Operations'], intelligence:['Risk & Finance','Financial Intelligence'], support:['Players','Support & Disputes'], users:['Accounts','Users'], games:['Arena','Games & Live'], payments:['Finance','Payments'], compliance:['Safety','Compliance'],
  banners:['Content','Home Media'], vip:['Loyalty','VIP Management'], appearance:['Brand','Theme & Logo'], social:['Community','Social Media'],
  settings:['Platform','Settings'], team:['Security','Team & Access'], audit:['Security','Audit Log'],
};
const state = {chinaFeed:null,route:routeFromHash(),loading:true,busy:false,error:'',toast:null,modal:null,mobileOpen:false,authRequired:false,authStep:'credentials',authChallenge:'',authError:'',admin:null,overview:{},operations:{incidents:[],backups:[],notifications:[]},intelligence:{funds:{},payments:{},betting:{},alerts:{},daily:[],policy:{}},intelligenceAlerts:{results:[],summary:{}},support:{results:[],summary:{}},users:[],games:[],streams:[],streamHealth:{},paymentAccounts:[],paymentRequests:[],compliance:[],compliancePolicy:{},banners:[],vip:[],config:{},risk:{},team:[],audit:[]};

function routeFromHash(){const route=window.location.hash.replace(/^#/,'').split('?')[0];return routes.includes(route)?route:'overview';}
function localDateTime(value=''){if(!value)return '';const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value).slice(0,16);return new Date(date-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function initials(value='Admin'){return value.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();}
function hasPermission(permission){const permissions=state.admin?.permissions||[];return localPreview||permissions.includes('*')||permissions.includes(permission);}
const routePermissions={overview:'overview',operations:'operations',intelligence:'intelligence',support:'support',users:'users',games:'games',payments:'payments',compliance:'compliance',banners:'banners',vip:'vip',appearance:'theme',social:'social',settings:'settings',team:'team',audit:'audit'};
function navItem(route,label,iconName,count=0){return `<button class="admin-nav__item ${state.route===route?'is-active':''}" type="button" data-route="${route}">${icon(iconName,19)}<span>${escapeHtml(label)}</span>${count?`<i>${count>99?'99+':count}</i>`:''}</button>`;}

function shell(content){
  const pending=state.paymentRequests.filter(item=>item.status==='PENDING').length;const alerts=Number(state.operations.unread_admin_notifications||0);const [eyebrow,title]=routeInfo[state.route];const admin=state.admin||{display_name:'Preview Admin',role:'Super Admin'};
  const nav=(route,label,iconName,count=0)=>hasPermission(routePermissions[route])?navItem(route,label,iconName,count):'';
  const logoUrl=state.config.brand?.logo_url||'/static/ic_rooster.svg';const customLogo=logoUrl!=='/static/ic_rooster.svg';
  return `<div class="admin-shell ${state.mobileOpen?'is-menu-open':''}"><aside class="admin-sidebar"><a class="admin-brand" href="#overview" data-route="overview" aria-label="RoosterRun Admin home"><img class="${customLogo?'is-custom-logo':''}" data-admin-logo src="${escapeHtml(logoUrl)}" alt=""><span><strong>${escapeHtml(state.config.brand?.site_name||'RoosterRun')}</strong><small>ADMIN CONSOLE</small></span></a><nav class="admin-nav" aria-label="Administration"><small>OPERATIONS</small>${nav('overview','Overview','overview')}${nav('operations','Reliability','activity',Number(state.operations.open_incidents||0))}${nav('intelligence','Risk & Finance','intelligence',Number(state.intelligenceAlerts.summary?.high_risk||0))}${nav('support','Support & Disputes','support',Number(state.support.summary?.active||0))}${nav('users','Users','users')}${nav('games','Games & Live','game')}${nav('payments','Payments','payments',pending)}${nav('compliance','Compliance','shield',state.compliance.filter(item=>['PENDING','REVIEW_REQUIRED'].includes(item.status)).length)}${nav('banners','Home Media','banner')}${nav('vip','VIP Management','vip')}<small>BRAND & PLATFORM</small>${nav('appearance','Theme & Logo','palette')}${nav('social','Social Media','social')}${nav('settings','Settings','settings')}${nav('team','Team & Access','shield')}${nav('audit','Audit Log','audit')}</nav><div class="admin-profile"><span>${initials(admin.display_name)}</span><div><strong>${escapeHtml(admin.display_name)}</strong><small>${escapeHtml(localPreview?'Local preview':admin.role||'Protected session')}</small></div><button type="button" data-action="sign-out" aria-label="End admin session">${icon('more',19)}</button></div></aside><button class="admin-scrim" type="button" data-action="close-menu" aria-label="Close navigation"></button><main class="admin-main"><header class="admin-topbar"><div class="admin-topbar__title"><button class="mobile-menu-button" type="button" data-action="open-menu" aria-label="Open navigation">${icon('menu',21)}</button><div><small>${escapeHtml(eyebrow)}</small><strong>${escapeHtml(title)}</strong></div></div><div class="admin-top-actions"><button type="button" data-route="operations" aria-label="Open operations notifications">${icon('bell',19)}${alerts?'<i></i>':''}</button><a href="/play/#dashboard" aria-label="Open player app">${icon('external',17)}<span>Player app</span></a></div></header><div class="admin-content">${content}</div></main><div id="admin-overlay">${renderModal()}</div><div class="toast-stack" aria-live="polite">${state.toast?`<div class="toast toast--${escapeHtml(state.toast.tone)}">${icon(state.toast.tone==='error'?'alert':'check',18)}<span>${escapeHtml(state.toast.message)}</span></div>`:''}</div></div>`;
}
function renderAuth(){const mfa=state.authStep==='mfa';return `<main class="admin-auth"><section><img src="/static/ic_rooster.svg" alt=""><span>ROOSTERRUN ADMIN</span><h1>${mfa?'Security verification':'Administrator access'}</h1><p>${mfa?'Enter the six-digit code from your authenticator app or use one unused recovery code.':'Sign in with an assigned staff account. Access is limited by role and every sensitive change is audited.'}</p><form id="admin-auth-form">${mfa?`<label><span>Authentication code</span><input name="code" autocomplete="one-time-code" inputmode="numeric" required autofocus></label>`:`<label><span>Username</span><input name="username" autocomplete="username" required autofocus></label><label><span>Password</span><input name="password" type="password" autocomplete="current-password" required></label>`}${state.authError?`<div class="admin-auth__error">${escapeHtml(state.authError)}</div>`:''}${button(state.busy?'Checking…':mfa?'Verify and continue':'Sign in',{type:'submit',tone:'primary',iconName:'shield',disabled:state.busy})}</form>${mfa?'<button class="text-button" type="button" data-action="cancel-admin-mfa">Use another account</button>':''}<a href="/play/#dashboard">Return to player app</a></section></main>`;}
function loadingView(){return `<div class="admin-loading"><img src="/static/ic_rooster.svg" alt=""><strong>Preparing admin operations</strong><span>Loading secure platform data…</span></div>`;}
function errorView(){return `<div class="admin-error">${icon('alert',28)}<h2>Dashboard could not load</h2><p>${escapeHtml(state.error)}</p>${button('Try again',{action:'retry-load',tone:'primary'})}</div>`;}

function overviewView(){
  const data=state.overview;const pending=state.paymentRequests.filter(item=>item.status==='PENDING');const live=state.games.find(game=>['LIVE','BETTING_OPEN','BETTING_CLOSED'].includes(game.status));const activeBanner=state.banners.find(item=>item.active);const queue=[];
  if(pending.length)queue.push({tone:'gold',title:`${pending.length} payment request${pending.length===1?'':'s'} need verification`,copy:`${money(pending.reduce((sum,item)=>sum+Number(item.amount||0),0))} in the review queue`,route:'payments',action:'Review payments'});
  if(Number(state.intelligenceAlerts.summary?.high_risk||0))queue.push({tone:'red',title:`${state.intelligenceAlerts.summary.high_risk} high-risk financial alert${state.intelligenceAlerts.summary.high_risk===1?'':'s'}`,copy:'Review recorded evidence before taking any account or payment action',route:'intelligence',action:'Investigate'});
  if(Number(state.support.summary?.active||0))queue.push({tone:state.support.summary.overdue?'red':'blue',title:`${state.support.summary.active} active support case${state.support.summary.active===1?'':'s'}`,copy:state.support.summary.overdue?`${state.support.summary.overdue} case${state.support.summary.overdue===1?' is':'s are'} beyond the response SLA`:`${state.support.summary.unassigned||0} new case${state.support.summary.unassigned===1?'':'s'} need assignment`,route:'support',action:'Open support'});
  if(live)queue.push({tone:'red',title:live.title,copy:`${live.status.replace(/_/g,' ')} · ${live.arena}`,route:'games',action:'Open game'});
  if(activeBanner)queue.push({tone:'blue',title:'Active player banner',copy:`${activeBanner.title} · ${activeBanner.placement.replace(/_/g,' ')}`,route:'banners',action:'Manage banners'});
  const engineHealthy=Boolean(data.engine?.scheduler_running);
  const streamingReady=Boolean(data.streaming?.media_plane_configured);
  const healthActions=engineHealthy&&streamingReady?'<span class="health-pill">All systems normal</span>':streamingReady?'<span class="health-pill">Engine attention</span>':'<span class="health-pill">Media setup required</span>';
  return `${pageHeader('LIVE OPERATIONS','Command center','Monitor the player platform, cash queue, and arena from one place.',button('Create game',{action:'new-game',tone:'primary',iconName:'plus'}))}<section class="metrics-grid">${metric('users','Total users',String(data.users||0),`${data.vip_users||0} VIP members`,'blue')}${metric('payments','Pending payments',String(data.pending_payments||0),money(data.pending_payment_amount||0),'gold')}${metric('live','Active games',String(data.active_games||0),live?live.title:'No arena live','green')}${metric('banner','Active banners',String(data.active_banners||0),'Public placements','violet')}</section><div class="dashboard-grid">${panel('Operations queue','Requires action',queue.length?`<div class="operations-queue">${queue.map(item=>`<article><i class="queue-marker queue-marker--${item.tone}"></i><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.copy)}</p></div><button type="button" data-route="${item.route}">${escapeHtml(item.action)}${icon('chevron',15)}</button></article>`).join('')}</div>`:empty('check','Queue is clear','There are no urgent operations right now.'),'<button class="text-button" type="button" data-route="audit">View activity</button>')}${panel('System status','Platform health',`<div class="health-list"><div><span><i></i>Player website</span><strong>Online</strong></div><div><span><i></i>Payment service</span><strong>Online</strong></div><div><span><i></i>Cockfight engines</span><strong>${engineHealthy?'Running':'Attention'}</strong></div><div><span>${icon('clock',16)}Server time</span><b>${dateTime(data.engine?.checked_at||new Date().toISOString())}</b></div></div>`,healthActions)}${panel('Recent activity','Security & changes',state.audit.length?`<div class="activity-list">${state.audit.slice(0,6).map(row=>`<article><span>${icon(row.module==='Payments'?'payments':row.module==='Games'?'game':'activity',17)}</span><div><strong>${escapeHtml(row.action)}</strong><p>${escapeHtml(row.subject||row.module)}</p></div><time>${dateTime(row.created_at)}</time></article>`).join('')}</div>`:empty('audit','No administrator changes','New actions will appear here.'))}</div>`;
}

function operationsView(){
  const data=state.operations||{};const incidents=data.incidents||[];const active=incidents.filter(item=>item.status!=='RESOLVED');const run=data.latest_reconciliation;const backups=data.backups||[];const lastBackup=backups[0];const findings=run?.findings||[];
  const healthRows=[['Database',data.database?.status||'unknown',data.database?.integrity||'Not checked'],['Match scheduler',data.cockfight?.scheduler?'running':'attention',`${data.cockfight?.pending_bets||0} pending bets`],['Stream monitor',data.streaming?.monitor_running?'running':'attention',`${data.streaming?.degraded||0} degraded sessions`],['Private compliance storage',data.compliance?.private_storage?'protected':'attention',data.compliance?.operating_mode||'Unknown mode']];
  const actions=`<div class="page-actions">${button('Run reconciliation',{action:'run-reconciliation',tone:'secondary',iconName:'activity',disabled:state.busy})}${button('Create private backup',{action:'create-backup',tone:'primary',iconName:'backup',disabled:state.busy})}</div>`;
  return `${pageHeader('OPERATIONS & RELIABILITY','System control','Monitor engine health, reconcile financial state, manage incidents, and create verified private recovery archives.',actions)}<section class="metrics-grid">${metric('alert','Open incidents',String(active.length),active.some(item=>item.severity==='CRITICAL')?'Critical attention required':'No critical conditions','red')}${metric('activity','Last reconciliation',run?.status||'Not run',run?dateTime(run.completed_at):'Run the first integrity scan',run?.status==='PASS'?'green':'gold')}${metric('backup','Last backup',lastBackup?.status||'Not created',lastBackup?dateTime(lastBackup.created_at):'Create a recovery point','blue')}${metric('bell','In-app alerts',String(data.unread_admin_notifications||0),'SMS and email remain disabled','violet')}</section><div class="operations-layout">${panel('Engine health','Live checks',`<div class="operations-health">${healthRows.map(([label,status,copy])=>`<article><span class="health-dot health-dot--${status==='running'||status==='ok'||status==='protected'?'ok':'warn'}"></span><div><strong>${escapeHtml(label)}</strong><p>${escapeHtml(copy)}</p></div>${badge(status)}</article>`).join('')}</div>`,`<span class="health-pill">Checked ${dateTime(data.checked_at)}</span>`)}${panel('Financial reconciliation','Read-only integrity scan',run?`<div class="reconciliation-summary"><span class="reconciliation-score reconciliation-score--${String(run.status).toLowerCase()}">${icon(run.status==='PASS'?'check':'alert',24)}${escapeHtml(run.status)}</span><div><strong>${escapeHtml(run.reference)}</strong><p>${run.check_count} checks · ${run.critical_count} critical · ${run.warning_count} warnings</p><small>Completed ${dateTime(run.completed_at)} by ${escapeHtml(run.initiated_by)}</small></div></div>${findings.length?`<div class="finding-list">${findings.map(item=>`<article><span>${badge(item.severity)}</span><div><strong>${escapeHtml(item.check_code.replace(/_/g,' '))}</strong><p>${escapeHtml(item.message)}</p><small>${escapeHtml(item.entity_type)} ${escapeHtml(item.entity_id)} · expected ${escapeHtml(item.expected)} · found ${escapeHtml(item.actual)}</small></div></article>`).join('')}</div>`:empty('check','Ledgers are consistent','Payment entries, bet holds, settlements, available balances, and SQLite integrity all passed.')}`:empty('activity','No reconciliation run','Run the first read-only integrity scan.'))}${panel('Incident response','Acknowledgement and resolution',active.length?`<div class="incident-list">${active.map(item=>`<article><span class="incident-severity incident-severity--${item.severity.toLowerCase()}">${icon('alert',18)}</span><div><header><strong>${escapeHtml(item.title)}</strong>${badge(item.status)}</header><p>${escapeHtml(item.description)}</p><small>${escapeHtml(item.reference)} · seen ${item.occurrence_count} time${item.occurrence_count===1?'':'s'} · ${dateTime(item.last_seen_at)}</small></div><footer>${item.status==='OPEN'?button('Acknowledge',{action:'ack-incident',tone:'secondary',extra:`data-id="${item.id}"`}):''}${button('Resolve',{action:'resolve-incident',tone:'primary',extra:`data-id="${item.id}"`})}</footer></article>`).join('')}</div>`:empty('check','No active incidents','New critical reconciliation or backup failures will appear here.'))}${panel('Recovery archives','Private verified backups',backups.length?`<div class="backup-list">${backups.map(item=>`<article><span>${icon('database',20)}</span><div><strong>${escapeHtml(item.reference)}</strong><p>${item.contents?.upload_files||0} uploads · ${item.contents?.identity_files||0} identity files · ${Math.max(1,Math.ceil(Number(item.size_bytes||0)/1024))} KB</p><small>SHA-256 ${escapeHtml(String(item.sha256||'').slice(0,18))}… · ${dateTime(item.verified_at||item.created_at)}</small></div>${badge(item.status)}${item.download_url?`<a class="icon-action" href="${escapeHtml(item.download_url)}" aria-label="Download ${escapeHtml(item.reference)}">${icon('backup',17)}</a>`:''}</article>`).join('')}</div>`:empty('backup','No private backup','Create the first database, uploads, and identity archive.'),'<span class="health-pill">Restore is deliberately offline-only</span>')}${panel('Notification delivery','Channel status',`<div class="delivery-list"><article><span>${icon('bell',18)}</span><div><strong>In-app notifications</strong><p>Durable player and administrator messages</p></div>${badge(data.external_delivery?.in_app||'ACTIVE')}</article><article><span>${icon('external',18)}</span><div><strong>SMS delivery</strong><p>No provider configured; nothing is sent externally</p></div>${badge(data.external_delivery?.sms||'NOT_CONFIGURED')}</article><article><span>${icon('external',18)}</span><div><strong>Email delivery</strong><p>No provider configured; nothing is sent externally</p></div>${badge(data.external_delivery?.email||'NOT_CONFIGURED')}</article></div>`)}</div>`;
}

function intelligenceView(){
  const data=state.intelligence||{};const funds=data.funds||{};const betting=data.betting||{};const payments=data.payments||{};const alerts=state.intelligenceAlerts?.results||[];const summary=state.intelligenceAlerts?.summary||{};const daily=data.daily||[];const max=Math.max(1,...daily.map(day=>Number(day.deposits||0)+Number(day.stakes||0)));const policy=data.policy||{};
  const actions=`<div class="page-actions">${button('Export evidence',{action:'export-intelligence',tone:'secondary',iconName:'backup',disabled:state.busy})}${button(state.busy?'Scanning…':'Run detection scan',{action:'run-intelligence-scan',tone:'primary',iconName:'intelligence',disabled:state.busy})}</div>`;
  const paymentLine=(label,item={})=>`<div><span>${escapeHtml(label)}</span><strong>${item.count||0}</strong><b>${money(item.amount||0)}</b></div>`;
  return `${pageHeader('FINANCIAL INTELLIGENCE','Risk & finance','Understand platform funds, payment movement, betting exposure, and review-first anomaly signals.',actions)}<aside class="info-strip intelligence-boundary">${icon('shield',19)}<div><strong>Detection never moves money or suspends a player automatically</strong><p>Every alert requires a human decision and a recorded review reason.</p></div><span>${data.latest_scan?`Last scan ${dateTime(data.latest_scan.completed_at)}`:'No scan yet'}</span></aside><section class="metrics-grid">${metric('payments','Available funds',money(funds.available||0),`${money(funds.wallet_balance||0)} wallet balance`,'green')}${metric('activity','Open liability',money(betting.open_liability||0),`${betting.pending||0} pending bet tickets`,'gold')}${metric('intelligence','Active alerts',String(summary.active||0),`${summary.high_risk||0} high or critical`,'red')}${metric('game','Gross result',money(betting.gross_result||0),`${money(betting.stakes||0)} stakes · ${money(betting.payouts||0)} payouts`,'blue')}</section><div class="intelligence-layout">${panel('Fourteen-day movement','Approved payments and bet stakes',daily.length?`<div class="finance-chart" aria-label="Fourteen-day financial movement">${daily.map(day=>{const deposit=Math.round(Number(day.deposits||0)/max*100);const stakes=Math.round(Number(day.stakes||0)/max*100);return `<div title="${escapeHtml(day.date)} · deposits ${money(day.deposits)} · stakes ${money(day.stakes)}"><span><i style="height:${deposit}%"></i><b style="height:${stakes}%"></b></span><small>${escapeHtml(day.date.slice(5))}</small></div>`;}).join('')}</div><div class="finance-legend"><span><i></i>Approved deposits</span><span><b></b>Bet stakes</span></div>`:empty('activity','No financial movement','Approved transactions and bets will create the trend.'))}${panel('Payment position','All retained requests',`<div class="payment-position"><section><header><strong>Deposits</strong><span>${money(payments.DEPOSIT?.APPROVED?.amount||0)} approved</span></header>${paymentLine('Pending',payments.DEPOSIT?.PENDING)}${paymentLine('Approved',payments.DEPOSIT?.APPROVED)}${paymentLine('Rejected',payments.DEPOSIT?.REJECTED)}</section><section><header><strong>Withdrawals</strong><span>${money(payments.WITHDRAWAL?.PENDING?.amount||0)} held</span></header>${paymentLine('Pending',payments.WITHDRAWAL?.PENDING)}${paymentLine('Approved',payments.WITHDRAWAL?.APPROVED)}${paymentLine('Rejected',payments.WITHDRAWAL?.REJECTED)}</section></div>`)}${panel('Investigation queue','Signals requiring a decision',alerts.length?`<div class="intelligence-alert-list">${alerts.map(alert=>`<article class="intelligence-alert intelligence-alert--${alert.severity.toLowerCase()}" data-search-row="${escapeHtml(`${alert.reference} ${alert.user_id} ${alert.title} ${alert.alert_type} ${alert.status}`.toLowerCase())}"><span class="intelligence-score">${alert.score}<small>score</small></span><div><header>${badge(alert.severity)}${badge(alert.status)}<small>${dateTime(alert.detected_at)}</small></header><strong>${escapeHtml(alert.title)}</strong><p>${escapeHtml(alert.description)}</p><small>${escapeHtml(alert.reference)} · ${escapeHtml(alert.user_id||'Platform')} ${alert.linked_reference?`· ${escapeHtml(alert.linked_reference)}`:''}</small></div>${button('Investigate',{action:'review-intelligence',tone:'secondary',iconName:'chevron',extra:`data-id="${alert.id}"`})}</article>`).join('')}</div>`:empty('check','No anomaly alerts','Run a detection scan after financial activity is recorded.'),`<span class="queue-count">${summary.active||0}</span>`)}<form id="intelligence-policy-form" class="panel form-panel intelligence-policy"><header class="panel__header"><div><small>DETECTION POLICY</small><h2>Review thresholds</h2></div><span class="health-pill">Server enforced</span></header><div class="form-grid">${field({name:'large_withdrawal_rupees',label:'Large withdrawal (₹)',type:'number',value:policy.large_withdrawal_rupees??100000,min:500,max:10000000})}${field({name:'rapid_cashout_minutes',label:'Deposit-to-withdrawal window (minutes)',type:'number',value:policy.rapid_cashout_minutes??120,min:5,max:1440})}${field({name:'rapid_cashout_percent',label:'Rapid cash-out share (%)',type:'number',value:policy.rapid_cashout_percent??75,min:10,max:100})}${field({name:'rejected_payments_24h',label:'Rejected payments in 24 hours',type:'number',value:policy.rejected_payments_24h??3,min:2,max:50})}${field({name:'rejected_risk_checks_15m',label:'Rejected risk checks in 15 minutes',type:'number',value:policy.rejected_risk_checks_15m??3,min:2,max:100})}${field({name:'betting_velocity_5m',label:'Bets in five minutes',type:'number',value:policy.betting_velocity_5m??6,min:2,max:100})}${field({name:'betting_velocity_stake_rupees',label:'Five-minute stake threshold (₹)',type:'number',value:policy.betting_velocity_stake_rupees??20000,min:100,max:10000000})}${field({name:'shared_beneficiary_users',label:'Accounts sharing beneficiary',type:'number',value:policy.shared_beneficiary_users??2,min:2,max:20})}</div><footer>${button('Save detection policy',{type:'submit',tone:'primary',iconName:'check'})}</footer></form></div>`;
}

function supportView(){
  const data=state.support||{results:[],summary:{}};const tickets=data.results||[];const summary=data.summary||{};
  return `${pageHeader('PLAYER CARE','Support & Disputes','Investigate account, payment, bet, stream, and safety cases in one auditable queue.')}<section class="metrics-grid">${metric('support','Active cases',String(summary.active||0),'Open, in review, or waiting','blue')}${metric('users','Unassigned',String(summary.unassigned||0),'New cases needing ownership','gold')}${metric('alert','Overdue SLA',String(summary.overdue||0),summary.overdue?'Immediate attention required':'Response targets are on track','red')}${metric('check','All cases',String(summary.total||0),'Complete retained history','green')}</section><section class="toolbar"><label>${icon('search',17)}<input data-table-search="support" type="search" placeholder="Search case, player, subject, or reference"></label><span>${tickets.length} cases</span></section><section class="support-grid">${tickets.map(ticket=>{const link=ticket.linked_payment_reference||ticket.linked_bet_reference||'';return `<article class="support-card ${ticket.sla_overdue?'is-overdue':''}" data-search-row="${escapeHtml(`${ticket.reference} ${ticket.user_id} ${ticket.subject} ${ticket.category} ${ticket.status} ${ticket.priority} ${link}`.toLowerCase())}"><header><div>${badge(ticket.status)}${badge(ticket.priority)}</div><time class="support-sla ${ticket.sla_overdue?'is-overdue':''}">${icon(ticket.sla_overdue?'alert':'clock',15)}${ticket.sla_overdue?'SLA overdue':`Due ${dateTime(ticket.sla_due_at)}`}</time></header><h2>${escapeHtml(ticket.subject)}</h2><p>${escapeHtml(ticket.messages?.at(-1)?.body||'No message')}</p><dl><div><dt>Case</dt><dd>${escapeHtml(ticket.reference)}</dd></div><div><dt>Player</dt><dd>${escapeHtml(ticket.user_id)}</dd></div><div><dt>Category</dt><dd>${escapeHtml(ticket.category.replace(/_/g,' '))}</dd></div><div><dt>Linked record</dt><dd>${escapeHtml(link||'None')}</dd></div></dl><footer><span>${ticket.assigned_admin?`Assigned to ${escapeHtml(ticket.assigned_admin)}`:'Not assigned'} · ${ticket.messages?.length||0} message${ticket.messages?.length===1?'':'s'}</span>${button('Review case',{action:'review-support',tone:'secondary',iconName:'chevron',extra:`data-id="${ticket.id}"`})}</footer></article>`;}).join('')}${tickets.length?'':empty('support','No support cases','New player requests will appear here with their response deadline.')}</section>`;
}

function usersView(){return `${pageHeader('PLAYER ACCOUNTS','Users','Search players, review wallet state, suspend access, and assign VIP tiers.')}<section class="toolbar"><label>${icon('search',17)}<input data-table-search="users" type="search" placeholder="Search name, ID, or mobile"></label><span>${state.users.length} accounts</span></section><section class="table-card"><div class="table-scroll"><table><thead><tr><th>User</th><th>Wallet</th><th>Payments</th><th>VIP tier</th><th>Status</th><th></th></tr></thead><tbody>${state.users.map(user=>`<tr data-search-row="${escapeHtml(`${user.display_name} ${user.user_id} ${user.mobile}`.toLowerCase())}"><td><div class="user-cell"><span>${initials(user.display_name)}</span><div><strong>${escapeHtml(user.display_name)}</strong><small>${escapeHtml(user.user_id)}${user.mobile?` · ${escapeHtml(user.mobile)}`:''}</small></div></div></td><td><strong>${money(user.balance)}</strong></td><td><span>${user.payment_count} total</span>${user.pending_count?`<small class="warning-copy">${user.pending_count} pending</small>`:''}</td><td><span class="tier-pill" style="--tier:${escapeHtml(state.vip.find(tier=>tier.name===user.vip_tier)?.color||'#7F8796')}">${icon('vip',14)}${escapeHtml(user.vip_tier)}</span></td><td>${badge(user.status)}</td><td><button class="icon-action" type="button" data-action="edit-user" data-id="${escapeHtml(user.user_id)}" aria-label="Manage ${escapeHtml(user.display_name)}">${icon('edit',17)}</button></td></tr>`).join('')}</tbody></table></div>${state.users.length?'':empty('users','No users found','Player accounts will appear after registration.')}</section><aside class="info-strip">${icon('shield',19)}<div><strong>Account changes are audited</strong><p>Suspension blocks access; wallet balances are never changed from this screen.</p></div><span>${state.vip.length} configured tiers</span></aside>`;}

function activeStream(gameId){return state.streams.find(stream=>Number(stream.game_id)===Number(gameId)&&['CREATED','PAIRED','READY','LIVE','DEGRADED'].includes(stream.status));}
function streamControl(game){const stream=activeStream(game.id);if(stream?.status==='LIVE'||stream?.status==='DEGRADED')return button(stream.status==='LIVE'?'End live stream':'End degraded stream',{action:'stop-stream',tone:'secondary',iconName:'live',extra:`data-id="${escapeHtml(stream.id)}"`});if(stream)return button('Open camera studio',{action:'open-stream',tone:'secondary',iconName:'live',extra:`data-id="${escapeHtml(stream.id)}"`});if(['SETTLED','CANCELLED'].includes(game.status))return '';return button('Camera studio',{action:'create-stream',tone:'secondary',iconName:'live',extra:`data-id="${game.id}"`});}
function lifecycleControl(game){const next={DRAFT:['SCHEDULED','Schedule'],SCHEDULED:['BETTING_OPEN','Open betting'],BETTING_OPEN:['BETTING_CLOSED','Close betting'],BETTING_CLOSED:['LIVE','Go live']}[game.status];const stream=streamControl(game);if(next)return `${stream}${button(next[1],{action:'transition-game',tone:'primary',iconName:'arrow',extra:`data-id="${game.id}" data-status="${next[0]}"`})}`;if(game.status==='LIVE')return `${stream}${button('Declare result',{action:'declare-result',tone:'primary',iconName:'check',extra:`data-id="${game.id}"`})}`;if(game.status==='AWAITING_RESULT'||game.status==='CANCELLED')return `${stream}${button('Settle match',{action:'settle-game',tone:'primary',iconName:'payments',extra:`data-id="${game.id}"`})}`;return stream;}
function chinaFeedPanel(){const feed=state.chinaFeed;if(!feed)return '';const settings=feed.settings||{};const current=feed.current||{};const st=feed.state||{};const match=current.match;const tone=!settings.enabled?'gray':current.healthy?'green':'red';const status=!settings.enabled?'INACTIVE':current.healthy?(current.allow_betting?'BETTING_OPEN':'LIVE'):'ATTENTION';return `<section class="panel form-panel china-feed"><header class="panel__header"><div><small>CHINA 24/7 AUTO-MATCH</small><h2>Upstream feed</h2></div><div class="panel__actions">${badge(status)}${button('Poll now',{action:'china-poll',tone:'ghost',iconName:'refresh'})}${button('Recover results',{action:'china-recover',tone:'ghost',iconName:'history'})}</div></header><section class="metrics-grid metrics-grid--three">${metric('live','Current match',match?`#${match.match_number||match.id}`:'—',match?`${match.status} · upstream ${st.current_ref_id||''}`:'No mirrored match','gold')}${metric('clock','Last upstream success',st.last_success_at?dateTime(st.last_success_at):'Never',st.last_error?`Last error: ${st.last_error}`:`${st.consecutive_failures||0} consecutive failures`,st.last_error?'red':'green')}${metric('game','Mirrored matches',String((feed.recent_matches||[]).length),feed.worker?'Poller running':'Poller stopped','blue')}</section><form id="china-feed-form" class="form-grid">${switchField('enabled','Enable China 24/7 feed','Mirror every upstream fight as a live match; betting follows the upstream open/close flag.',Boolean(settings.enabled))}${switchField('feature_current_match','Feature current fight','Make the mirrored fight the featured match on the player home.',Boolean(settings.feature_current_match))}${field({name:'info_url',label:'Match info URL',value:settings.info_url||'',wide:true,required:true})}${field({name:'history_url',label:'History URL',value:settings.history_url||'',wide:true,required:true})}${field({name:'stream_url_override',label:'Stream override URL (optional)',value:settings.stream_url_override||'',wide:true,help:'Leave blank to use the upstream live URL.'})}${field({name:'title_prefix',label:'Title prefix',value:settings.title_prefix||''})}${field({name:'arena',label:'Arena',value:settings.arena||''})}${field({name:'team_a_name',label:'Red corner name',value:settings.team_a_name||''})}${field({name:'team_b_name',label:'Blue corner name',value:settings.team_b_name||''})}${field({name:'team_a_odds',label:'Red odds',type:'number',step:'0.01',min:1.01,max:100,value:settings.team_a_odds??1.85})}${field({name:'draw_odds',label:'Draw odds',type:'number',step:'0.01',min:1.01,max:100,value:settings.draw_odds??6})}${field({name:'team_b_odds',label:'Blue odds',type:'number',step:'0.01',min:1.01,max:100,value:settings.team_b_odds??1.85})}${field({name:'poll_seconds',label:'Poll every (s)',type:'number',min:2,max:60,value:settings.poll_seconds??3})}${field({name:'suspend_after_failures',label:'Suspend market after failures',type:'number',min:1,max:20,value:settings.suspend_after_failures??3})}<div class="form-actions form-field--wide">${button('Save feed settings',{type:'submit',tone:'primary',iconName:'save'})}</div></form>${(feed.recent_matches||[]).length?`<table class="data-table"><thead><tr><th>Match</th><th>Upstream ID</th><th>Status</th><th>Result</th><th>Source</th><th>Updated</th></tr></thead><tbody>${feed.recent_matches.slice(0,10).map(row=>`<tr><td>#${escapeHtml(row.match_number||row.game_id)}</td><td>${escapeHtml(row.ref_id)}</td><td>${badge(row.game_status||'—')}</td><td>${escapeHtml(row.game_result||'—')}</td><td>${escapeHtml(row.result_source||'—')}</td><td>${dateTime(row.updated_at)}</td></tr>`).join('')}</tbody></table>`:''}</section>`;}
function gamesView(){return `${pageHeader('COCKFIGHT OPERATIONS','Games & Live','Schedule matches, publish versioned odds, control lifecycle, and settle every ticket.',button('Schedule game',{action:'new-game',tone:'primary',iconName:'plus'}))}<section class="metrics-grid metrics-grid--three">${metric('live','Live or open',String(state.games.filter(game=>['LIVE','BETTING_OPEN','BETTING_CLOSED'].includes(game.status)).length),'Requires operator monitoring','green')}${metric('clock','Scheduled',String(state.games.filter(game=>game.status==='SCHEDULED').length),'Upcoming matches','blue')}${metric('game','Total matches',String(state.games.length),'All retained game records','gold')}</section>${chinaFeedPanel()}<section class="game-grid">${state.games.map(game=>`<article class="game-card ${game.featured?'is-featured':''}">${game.thumbnail_url?`<img class="game-card__thumbnail" src="${escapeHtml(game.thumbnail_url)}" alt="Thumbnail for ${escapeHtml(game.title)}">`:`<div class="game-card__thumbnail game-card__thumbnail--empty">${icon('image',28)}<span>No thumbnail</span></div>`}<header><div>${badge(game.status)}${game.featured?'<span class="featured-pill">Featured</span>':''}<span class="version-pill">v${game.state_version||1}</span></div><button class="icon-action" type="button" data-action="edit-game" data-id="${game.id}" aria-label="Edit game">${icon('edit',17)}</button></header><h2>${escapeHtml(game.title)}</h2><p>${escapeHtml(game.arena)} · ${dateTime(game.scheduled_at)}</p><div class="game-odds"><span><small>${escapeHtml(game.team_a_name)}</small><strong>${Number(game.team_a_odds).toFixed(2)}x</strong></span><span><small>Draw</small><strong>${Number(game.draw_odds).toFixed(2)}x</strong></span><span><small>${escapeHtml(game.team_b_name)}</small><strong>${Number(game.team_b_odds).toFixed(2)}x</strong></span></div><footer><span>${icon('live',16)}${escapeHtml(game.stream_type)}</span><span>${game.result?`Result: ${escapeHtml(game.result)}`:`Betting closes ${dateTime(game.betting_closes_at)}`}</span></footer><div class="engine-controls">${button('Odds engine',{action:'edit-odds',tone:'secondary',iconName:'activity',extra:`data-id="${game.id}"`})}${game.status!=='SETTLED'&&game.status!=='CANCELLED'?button('Result / cancel',{action:'declare-result',tone:'secondary',iconName:'shield',extra:`data-id="${game.id}"`}):''}${lifecycleControl(game)}</div></article>`).join('')}${state.games.length?'':empty('game','No games scheduled','Create the first cockfight match.')}</section>`;}

function accountSummary(account){return account.account_type==='UPI'?account.upi_id:`${account.bank_name} · ••••${String(account.account_number||'').slice(-4)}`;}
function paymentCard(request){const detail=request.request_type==='DEPOSIT'?`UTR ${request.user_utr||'Not supplied'}`:request.beneficiary?.method==='UPI'?request.beneficiary.upi_id:`${request.beneficiary?.bank_name||'Bank'} · ••••${String(request.beneficiary?.account_number||'').slice(-4)}`;return `<article class="payment-card"><header><div><span class="request-type request-type--${request.request_type.toLowerCase()}">${icon(request.request_type==='DEPOSIT'?'plus':'payments',15)}${escapeHtml(request.request_type)}</span>${badge(request.status)}</div><strong>${money(request.amount)}</strong></header><h3>${escapeHtml(request.reference)}</h3><p>${escapeHtml(request.user_id)} · ${escapeHtml(detail)}</p><small>${dateTime(request.created_at)}</small><div class="proof-links">${request.deposit_proof_url?`<a href="${safeUrl(request.deposit_proof_url)}" target="_blank" rel="noopener">${icon('image',15)}Deposit proof</a>`:''}${request.payout_proof_url?`<a href="${safeUrl(request.payout_proof_url)}" target="_blank" rel="noopener">${icon('image',15)}Payout proof</a>`:''}${request.payout_utr?`<span>UTR ${escapeHtml(request.payout_utr)}</span>`:''}</div>${request.admin_note?`<blockquote>${escapeHtml(request.admin_note)}</blockquote>`:''}${request.status==='PENDING'?button('Review request',{action:'review-payment',tone:'secondary',iconName:'arrow',extra:`data-id="${request.id}"`}):''}</article>`;}
function paymentsView(){const pending=state.paymentRequests.filter(item=>item.status==='PENDING');const reviewed=state.paymentRequests.filter(item=>item.status!=='PENDING');return `${pageHeader('INDIAN MANUAL PAYMENTS','Payments','Verify proofs and UTRs before approving deposits or completing withdrawals.',button('Add receiving account',{action:'new-payment-account',tone:'primary',iconName:'plus'}))}<section class="metrics-grid metrics-grid--three">${metric('payments','Pending requests',String(pending.length),money(pending.reduce((sum,item)=>sum+Number(item.amount||0),0)),'gold')}${metric('check','Approved',String(reviewed.filter(item=>item.status==='APPROVED').length),'Wallet ledger entries','green')}${metric('alert','Rejected',String(reviewed.filter(item=>item.status==='REJECTED').length),'Recorded with a reason','red')}</section>${panel('Receiving accounts','Deposit options',`<div class="account-grid">${state.paymentAccounts.map(account=>`<article class="payment-account ${account.active?'':'is-disabled'}"><span>${icon('payments',20)}</span><div><strong>${escapeHtml(account.label)}</strong><p>${escapeHtml(accountSummary(account))}</p><small>${escapeHtml(account.account_holder)}</small></div>${account.qr_url?`<a href="${safeUrl(account.qr_url)}" target="_blank" rel="noopener">QR</a>`:''}<button type="button" data-action="toggle-payment-account" data-id="${account.id}">${account.active?'Disable':'Enable'}</button></article>`).join('')}${state.paymentAccounts.length?'':empty('payments','No receiving accounts','Add UPI or bank details for player deposits.')}</div>`)}${panel('Verification queue','Pending requests',pending.length?`<div class="payment-grid">${pending.map(paymentCard).join('')}</div>`:empty('check','Queue is clear','No deposit or withdrawal is waiting for review.'),`<span class="queue-count">${pending.length}</span>`)}${panel('Recently reviewed','Audit history',reviewed.length?`<div class="payment-grid">${reviewed.slice(0,12).map(paymentCard).join('')}</div>`:empty('audit','No reviewed payments','Decisions will appear here.'))}`;}

function complianceView(){const queue=state.compliance.filter(item=>['PENDING','REVIEW_REQUIRED'].includes(item.status));const policy=state.compliancePolicy||{};return `${pageHeader('IDENTITY & PLAYER SAFETY','Compliance','Review age and identity evidence, manage jurisdiction blocks, and monitor player-protection controls.')}<aside class="info-strip legal-lock">${icon('shield',19)}<div><strong>Social-preview mode is locked</strong><p>Real-money operation and payment collection cannot be enabled from this dashboard. A future permitted-jurisdiction release requires a signed deployment entitlement.</p></div><span>${escapeHtml(policy.operating_mode||'SOCIAL_PREVIEW')}</span></aside><section class="metrics-grid metrics-grid--three">${metric('history','Review queue',String(queue.length),'Pending or more information','gold')}${metric('check','Verified',String(state.compliance.filter(item=>item.status==='VERIFIED').length),'Age and identity approved','green')}${metric('alert','Rejected',String(state.compliance.filter(item=>item.status==='REJECTED').length),'Reason recorded','red')}</section><form id="compliance-policy-form" class="panel form-panel compliance-policy"><header class="panel__header"><div><small>SAFEGUARD POLICY</small><h2>Verification and jurisdiction rules</h2></div><span class="health-pill">Server enforced</span></header><div class="form-grid">${field({name:'minimum_age',label:'Minimum age',type:'number',value:policy.minimum_age??18,min:18,max:99})}${field({name:'limit_increase_delay_hours',label:'Limit increase delay (hours)',type:'number',value:policy.limit_increase_delay_hours??24,min:1,max:168})}${field({name:'document_retention_days',label:'Document retention (days)',type:'number',value:policy.document_retention_days??365,min:30,max:3650})}${field({name:'blocked_state_codes',label:'Blocked state codes',value:(policy.blocked_state_codes||[]).join(', '),placeholder:'Example: KA, TS',help:'Operator-configured only. Obtain legal advice before changing.'})}${field({name:'legal_notice',label:'Player legal notice',value:policy.legal_notice||'',wide:true,required:true})}</div>${switchField('kyc_required_for_betting','Require verification before betting','Identity and age must be approved before a prediction is accepted.',Boolean(policy.kyc_required_for_betting))}${switchField('kyc_required_for_deposit','Require verification before deposit','Blocks new deposit requests until verification is approved.',Boolean(policy.kyc_required_for_deposit))}${switchField('kyc_required_for_withdrawal','Require verification before withdrawal','Blocks withdrawal requests until verification is approved.',Boolean(policy.kyc_required_for_withdrawal))}<footer>${button('Save safeguard policy',{type:'submit',tone:'primary',iconName:'check'})}</footer></form><section class="toolbar"><label>${icon('search',17)}<input data-table-search="compliance" type="search" placeholder="Search user, state, status, or document"></label><span>${state.compliance.length} profiles</span></section><section class="table-card"><div class="table-scroll"><table><thead><tr><th>Player</th><th>Age</th><th>State</th><th>Documents</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody>${state.compliance.map(item=>`<tr data-search-row="${escapeHtml(`${item.user_id} ${item.display_name} ${item.state_code} ${item.status} ${(item.documents||[]).map(doc=>doc.document_type).join(' ')}`.toLowerCase())}"><td><div class="user-cell"><span>${initials(item.display_name||item.user_id)}</span><div><strong>${escapeHtml(item.display_name||item.user_id)}</strong><small>${escapeHtml(item.mobile||item.user_id)}</small></div></div></td><td>${item.age??'—'}</td><td>${escapeHtml(item.state_code||'—')}</td><td><span>${(item.documents||[]).length} private file${(item.documents||[]).length===1?'':'s'}</span></td><td><small>${item.submitted_at?dateTime(item.submitted_at):'Not submitted'}</small></td><td>${badge(item.status)}</td><td>${item.status!=='NOT_SUBMITTED'?`<button class="icon-action" type="button" data-action="review-compliance" data-id="${escapeHtml(item.user_id)}" aria-label="Review ${escapeHtml(item.display_name||item.user_id)}">${icon('edit',17)}</button>`:''}</td></tr>`).join('')}</tbody></table></div>${state.compliance.length?'':empty('shield','No verification profiles','Player submissions will appear here.')}</section>`;}

function bannersView(){return `${pageHeader('PLAYER HOME CONTENT','Home Media','Control the home banner, live card, video sections, and highlights with uploaded files or secure links.',button('Add media',{action:'new-banner',tone:'primary',iconName:'plus'}))}<section class="banner-grid">${state.banners.map(item=>`<article class="banner-card ${item.active?'':'is-disabled'}"><div class="banner-preview" style="${item.image_url?`background-image:linear-gradient(90deg,rgba(0,0,0,.78),rgba(0,0,0,.2)),url('${escapeHtml(item.image_url)}')`:''}"><span>${escapeHtml(item.placement.replace(/_/g,' '))}</span><h2>${escapeHtml(item.title)}</h2><p>${escapeHtml(item.subtitle||'No supporting text')}</p>${item.media_url?`<b>${icon('play',13)} ${escapeHtml(item.media_type||'VIDEO')}${item.duration?` · ${escapeHtml(item.duration)}`:''}</b>`:item.cta_label?`<b>${escapeHtml(item.cta_label)}</b>`:''}</div><footer><div>${badge(item.active?'ACTIVE':'INACTIVE')}<small>Order ${item.sort_order}</small></div><button class="icon-action" type="button" data-action="edit-banner" data-id="${item.id}" aria-label="Edit ${escapeHtml(item.title)}">${icon('edit',17)}</button></footer></article>`).join('')}${state.banners.length?'':empty('banner','No managed home media','The built-in artwork remains visible until you add operator-managed content.')}</section>`;}
function vipView(){return `${pageHeader('PLAYER LOYALTY','VIP Management','Configure transparent turnover thresholds, cashback, and payout priority.',button('Add VIP tier',{action:'new-vip',tone:'primary',iconName:'plus'}))}<section class="vip-grid">${state.vip.map(tier=>`<article class="vip-card ${tier.active?'':'is-disabled'}" style="--tier-color:${escapeHtml(tier.color)}"><header><span>${icon('vip',25)}</span><button class="icon-action" type="button" data-action="edit-vip" data-id="${tier.id}" aria-label="Edit ${escapeHtml(tier.name)}">${icon('edit',17)}</button></header><h2>${escapeHtml(tier.name)}</h2><p>From ${money(tier.minimum_turnover)} turnover</p><dl><div><dt>Cashback</dt><dd>${Number(tier.cashback_percent).toFixed(2)}%</dd></div><div><dt>Payout priority</dt><dd>Level ${tier.withdrawal_priority}</dd></div><div><dt>Status</dt><dd>${tier.active?'Active':'Hidden'}</dd></div></dl></article>`).join('')}</section><aside class="info-strip">${icon('alert',19)}<div><strong>VIP benefits must follow your responsible-play policy</strong><p>Avoid incentives that encourage chasing losses or bypass player limits.</p></div></aside>`;}

function appearanceView(){const brand=state.config.brand||{};const theme=state.config.theme||{};return `${pageHeader('GLOBAL BRAND','Theme & Logo','Update shared colors and brand assets across the player and admin experiences.')}<div class="appearance-grid"><form id="appearance-form" class="panel form-panel"><header class="panel__header"><div><small>BRAND IDENTITY</small><h2>Logo and naming</h2></div></header><div class="form-grid">${mediaPicker({name:'logo',label:'Primary logo',value:brand.logo_url||'/static/ic_rooster.svg',kind:'image',help:'An uploaded file replaces the pasted link when both are provided.'})}${field({name:'site_name',label:'Site name',value:brand.site_name||'RoosterRun',required:true})}${field({name:'tagline',label:'Tagline',value:brand.tagline||'Live Arena',required:true})}</div><hr><div class="panel__header"><div><small>GLOBAL PALETTE</small><h2>Interface colors</h2></div></div><div class="color-grid">${[['primary','Primary gold'],['primary_bright','Primary highlight'],['background','Background'],['surface','Surface'],['text','Main text'],['danger','Danger'],['success','Success']].map(([name,label])=>`<label><span>${escapeHtml(label)}</span><div><input name="${name}" type="color" value="${escapeHtml(theme[name]||'#000000')}"><input name="${name}_text" value="${escapeHtml(theme[name]||'#000000')}" pattern="#[0-9A-Fa-f]{6}" maxlength="7"></div></label>`).join('')}</div><footer>${button('Save global appearance',{type:'submit',tone:'primary',iconName:'check'})}</footer></form><section class="panel brand-preview"><header class="panel__header"><div><small>LIVE PREVIEW</small><h2>Player header</h2></div></header><div class="brand-preview__canvas" style="--preview-primary:${escapeHtml(theme.primary||'#E8B84C')};--preview-bg:${escapeHtml(theme.background||'#090B0F')};--preview-text:${escapeHtml(theme.text||'#F7F8FB')}"><header><img src="${escapeHtml(brand.logo_url||'/static/ic_rooster.svg')}" alt=""><span><strong>${escapeHtml(brand.site_name||'RoosterRun')}</strong><small>${escapeHtml(brand.tagline||'Live Arena')}</small></span><b>₹12,450</b></header><div><span>LIVE ARENA</span><h3>Main Arena · Match 41</h3><p>Your selected colors apply globally after saving.</p><button type="button" data-action="open-player-live">Watch live</button></div></div><p class="preview-note">The public app loads the saved theme from the server. Existing artwork is not recolored.</p></section></div>`;}
function socialView(){const links=state.config.social||[];return `${pageHeader('COMMUNITY LINKS','Social Media','Publish only verified official profiles. Empty links stay hidden from players.')}<form id="social-form" class="panel social-form"><header class="panel__header"><div><small>OFFICIAL CHANNELS</small><h2>Public profiles</h2></div></header><div class="social-list">${links.map((link,index)=>`<div><span>${icon('social',19)}</span><strong>${escapeHtml(link.platform)}</strong><input type="hidden" name="platform_${index}" value="${escapeHtml(link.platform)}"><input name="url_${index}" type="url" value="${escapeHtml(link.url)}" placeholder="https://…"><label><input name="active_${index}" type="checkbox" ${link.active?'checked':''}><i></i><span>Visible</span></label></div>`).join('')}</div><footer>${button('Save social links',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`;}

function settingsView(){const general=state.config.general||{};const responsible=state.config.responsible||{};const notifications=state.config.notifications||{};const risk=state.risk||{};return `${pageHeader('PLATFORM CONTROL','Settings','Set operational defaults, player safeguards, risk limits, alerts, and staff permissions.')}<form id="settings-form" class="settings-grid"><section class="panel form-panel"><header class="panel__header"><div><small>GENERAL</small><h2>Platform defaults</h2></div></header><div class="form-grid">${selectField({name:'timezone',label:'Timezone',value:general.timezone||'Asia/Kolkata',options:[['Asia/Kolkata','India · Asia/Kolkata'],['Asia/Dubai','UAE · Asia/Dubai'],['UTC','UTC']]})}${selectField({name:'currency',label:'Currency',value:general.currency||'INR',options:[['INR','Indian Rupee (INR)']]})}${selectField({name:'language',label:'Default language',value:general.language||'English',options:['English','Hindi','Telugu']})}</div>${switchField('maintenance_mode','Maintenance mode','Temporarily stop public access while operators remain signed in.',Boolean(general.maintenance_mode))}</section><section class="panel form-panel"><header class="panel__header"><div><small>RESPONSIBLE PLAY</small><h2>Transaction limits</h2></div></header><div class="form-grid">${field({name:'minimum_age',label:'Minimum age',value:responsible.minimum_age??18,type:'number',min:18,max:99})}${field({name:'deposit_minimum',label:'Minimum deposit (₹)',value:responsible.deposit_minimum??100,type:'number',min:0})}${field({name:'deposit_maximum',label:'Maximum deposit (₹)',value:responsible.deposit_maximum??500000,type:'number',min:1})}${field({name:'withdrawal_minimum',label:'Minimum withdrawal (₹)',value:responsible.withdrawal_minimum??500,type:'number',min:0})}${field({name:'withdrawal_maximum',label:'Maximum withdrawal (₹)',value:responsible.withdrawal_maximum??200000,type:'number',min:1})}</div></section><section class="panel form-panel"><header class="panel__header"><div><small>RISK ENGINE</small><h2>Exposure and velocity</h2></div><span class="health-pill">Pre-bet enforced</span></header><div class="form-grid">${field({name:'risk_minimum_stake',label:'Minimum stake (₹)',type:'number',value:risk.minimum_stake??10,min:1})}${field({name:'risk_maximum_stake',label:'Maximum stake (₹)',type:'number',value:risk.maximum_stake??50000,min:10})}${field({name:'risk_maximum_user_exposure',label:'Maximum user exposure (₹)',type:'number',value:risk.maximum_user_exposure??200000,min:10})}${field({name:'risk_maximum_match_pool',label:'Maximum match pool (₹)',type:'number',value:risk.maximum_match_pool??2000000,min:100})}${field({name:'risk_maximum_outcome_liability',label:'Maximum outcome liability (₹)',type:'number',value:risk.maximum_outcome_liability??1000000,min:100})}${field({name:'risk_maximum_bets_per_minute',label:'Bets per minute',type:'number',value:risk.maximum_bets_per_minute??8,min:1,max:200})}${field({name:'risk_quote_ttl_seconds',label:'Quote lifetime (seconds)',type:'number',value:risk.quote_ttl_seconds??15,min:5,max:60})}</div></section><section class="panel form-panel"><header class="panel__header"><div><small>NOTIFICATIONS</small><h2>Operator alerts</h2></div></header>${switchField('payment_alerts','Payment requests','Alert staff when deposits or withdrawals enter the queue.',Boolean(notifications.payment_alerts))}${switchField('game_alerts','Game lifecycle','Alert staff before betting closes and when stream state changes.',Boolean(notifications.game_alerts))}${switchField('security_alerts','Security events','Alert super admins about access and account changes.',Boolean(notifications.security_alerts))}</section><section class="panel"><header class="panel__header"><div><small>ACCESS CONTROL</small><h2>Protected roles</h2></div><span class="health-pill">Server enforced</span></header><div class="role-list">${(state.config.roles||[]).map(role=>`<article><span>${icon('shield',18)}</span><div><strong>${escapeHtml(role.name)}</strong><p>${role.permissions.includes('*')?'Full platform access':escapeHtml(role.permissions.join(' · '))}</p></div><b>${role.protected?'Protected':'Custom'}</b></article>`).join('')}</div></section><footer class="settings-save">${button('Save platform settings',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`;}
function teamView(){const admin=state.admin||{};return `${pageHeader('SECURE OPERATIONS','Team & Access','Create named staff accounts, assign least-privilege roles, and require multi-factor authentication.',button('Add administrator',{action:'new-admin',tone:'primary',iconName:'plus'}))}<section class="metrics-grid metrics-grid--three">${metric('users','Staff accounts',String(state.team.length),`${state.team.filter(item=>item.active).length} active`,'blue')}${metric('shield','MFA enabled',String(state.team.filter(item=>item.mfa_enabled).length),'Authenticator protected','green')}${metric('audit','Your role',admin.role||'Preview',admin.mfa_enabled?'MFA protected':'MFA setup recommended','gold')}</section><section class="table-card"><div class="table-scroll"><table><thead><tr><th>Administrator</th><th>Role</th><th>MFA</th><th>Last sign in</th><th>Status</th><th></th></tr></thead><tbody>${state.team.map(member=>`<tr><td><div class="user-cell"><span>${initials(member.display_name)}</span><div><strong>${escapeHtml(member.display_name)}</strong><small>${escapeHtml(member.username)}</small></div></div></td><td>${escapeHtml(member.role)}</td><td>${badge(member.mfa_enabled?'ENABLED':'PENDING')}</td><td><small>${member.last_login_at?dateTime(member.last_login_at):'Never'}</small></td><td>${badge(member.active?'ACTIVE':'DISABLED')}</td><td><button class="icon-action" type="button" data-action="edit-admin" data-id="${member.id}" aria-label="Manage ${escapeHtml(member.display_name)}">${icon('edit',17)}</button></td></tr>`).join('')}</tbody></table></div>${state.team.length?'':empty('users','No staff accounts','Create the first named administrator account.')}</section><aside class="info-strip">${icon('shield',19)}<div><strong>${admin.mfa_enabled?'Your account uses multi-factor authentication':'Protect your own administrator account'}</strong><p>${localPreview?'MFA enrollment is available after signing in with a real administrator account.':'Use an authenticator app and store the one-time recovery codes offline.'}</p></div>${!localPreview&&!admin.mfa_enabled?button('Enable MFA',{action:'enroll-mfa',tone:'secondary'}):''}</aside>`;}
function auditView(){return `${pageHeader('SECURITY HISTORY','Audit Log','Review who changed configuration, payments, games, content, and accounts.')}<section class="toolbar"><label>${icon('search',17)}<input data-table-search="audit" type="search" placeholder="Search actor, module, action, or subject"></label><span>${state.audit.length} entries</span></section><section class="table-card"><div class="table-scroll"><table><thead><tr><th>Time</th><th>Actor</th><th>Module</th><th>Action</th><th>Subject</th><th>Details</th></tr></thead><tbody>${state.audit.map(row=>`<tr data-search-row="${escapeHtml(`${row.actor_id} ${row.actor_role} ${row.module} ${row.action} ${row.subject} ${row.details}`.toLowerCase())}"><td><small>${dateTime(row.created_at)}</small></td><td><strong>${escapeHtml(row.actor_id||'SYSTEM')}</strong><small>${escapeHtml(row.actor_role||'SYSTEM')}</small></td><td><span class="module-pill">${escapeHtml(row.module)}</span></td><td><strong>${escapeHtml(row.action)}</strong></td><td>${escapeHtml(row.subject||'—')}</td><td><small>${escapeHtml(row.details||'—')}</small></td></tr>`).join('')}</tbody></table></div>${state.audit.length?'':empty('audit','No audit entries','Sensitive administrator actions will appear here.')}</section>`;}
function view(){if(state.loading)return loadingView();if(state.error)return errorView();if(!hasPermission(routePermissions[state.route]))return empty('shield','Access restricted','Your administrator role does not include this module.');return ({overview:overviewView,operations:operationsView,intelligence:intelligenceView,support:supportView,users:usersView,games:gamesView,payments:paymentsView,compliance:complianceView,banners:bannersView,vip:vipView,appearance:appearanceView,social:socialView,settings:settingsView,team:teamView,audit:auditView}[state.route]||overviewView)();}

function renderModal(){if(!state.modal)return '';const {type,item={}}=state.modal;if(type==='intelligence')return intelligenceModal(item);if(type==='support')return supportModal(item);if(type==='game')return gameModal(item);if(type==='odds')return oddsModal(item);if(type==='result')return resultModal(item);if(type==='stream')return streamModal(item);if(type==='banner')return bannerModal(item);if(type==='vip')return vipModal(item);if(type==='user')return userModal(item);if(type==='account')return accountModal();if(type==='payment')return paymentModal(item);if(type==='compliance')return complianceModal(item);if(type==='admin')return adminModal(item);if(type==='mfa')return mfaModal(item);return '';}
function intelligenceModal(alert){const evidence=Object.entries(alert.evidence||{});return modal(`${alert.reference} · ${alert.title}`,'Financial investigation',`<form id="intelligence-alert-form" class="modal-form"><input type="hidden" name="id" value="${alert.id}"><div class="intelligence-review-head"><span class="intelligence-score">${alert.score}<small>risk score</small></span><div>${badge(alert.severity)}${badge(alert.status)}<h3>${escapeHtml(alert.description)}</h3><p>${escapeHtml(alert.user_id||'Platform-wide')} ${alert.linked_reference?`· ${escapeHtml(alert.linked_reference)}`:''}</p></div></div><section class="intelligence-evidence"><header><strong>Recorded evidence</strong><small>Detected ${dateTime(alert.detected_at)}</small></header>${evidence.map(([key,value])=>`<div><span>${escapeHtml(key.replace(/_/g,' '))}</span><strong>${escapeHtml(Array.isArray(value)?value.join(', '):typeof value==='object'?JSON.stringify(value):value)}</strong></div>`).join('')}</section><div class="form-grid">${selectField({name:'status',label:'Review decision',value:alert.status,options:[['OPEN','Open'],['REVIEWING','Under review'],['CLEARED','Cleared — no action'],['CONFIRMED','Confirmed concern']]})}${field({name:'assigned_admin',label:'Assigned analyst',value:alert.assigned_admin||state.admin?.display_name||'',placeholder:'Analyst name'})}<label class="form-field form-field--wide"><span>Review reason</span><textarea name="resolution_note" maxlength="1000" placeholder="Required before clearing or confirming the alert">${escapeHtml(alert.resolution_note||'')}</textarea></label></div><aside class="modal-note">${icon('shield',17)}This decision records evidence only. Wallets, payments, and account access remain unchanged.</aside><footer>${button('Cancel',{action:'close-modal'})}${button('Save investigation',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`,{size:'large'});}
function supportModal(ticket){const link=ticket.linked_payment_reference||ticket.linked_bet_reference||'';return modal(`${ticket.reference} · ${ticket.subject}`,'Support case',`<form id="support-case-form" class="modal-form"><input type="hidden" name="id" value="${ticket.id}"><div class="support-case-summary"><div><small>PLAYER</small><strong>${escapeHtml(ticket.user_id)}</strong></div><div><small>CATEGORY</small><strong>${escapeHtml(ticket.category.replace(/_/g,' '))}</strong></div><div><small>LINKED RECORD</small><strong>${escapeHtml(link||'None')}</strong></div><div><small>SLA</small><strong class="${ticket.sla_overdue?'warning-copy':''}">${ticket.sla_overdue?'Overdue':dateTime(ticket.sla_due_at)}</strong></div></div><div class="support-conversation">${(ticket.messages||[]).map(message=>`<article class="support-message support-message--${message.author_type.toLowerCase()} ${message.visibility==='INTERNAL'?'support-message--internal':''}"><header><strong>${message.visibility==='INTERNAL'?'Private staff note':message.author_type==='USER'?'Player':escapeHtml(message.author_id||'Support')}</strong><time>${dateTime(message.created_at)}</time></header><p>${escapeHtml(message.body)}</p></article>`).join('')}</div><div class="form-grid">${selectField({name:'status',label:'Case status',value:ticket.status,options:['OPEN','IN_REVIEW','WAITING_FOR_PLAYER','RESOLVED','CLOSED']})}${selectField({name:'priority',label:'Priority / SLA',value:ticket.priority,options:['LOW','NORMAL','HIGH','URGENT']})}${field({name:'assigned_admin',label:'Assigned administrator',value:ticket.assigned_admin||state.admin?.username||state.admin?.display_name||'',placeholder:'Staff username'})}<label class="form-field form-field--wide"><span>Resolution summary</span><textarea name="resolution_summary" maxlength="500" placeholder="Required when resolving or closing the case">${escapeHtml(ticket.resolution_summary||'')}</textarea></label><label class="form-field form-field--wide"><span>New message or staff note</span><textarea name="new_message" maxlength="1500" placeholder="Write a reply visible to the player, or mark it private below"></textarea></label></div><label class="check-field"><input name="internal" type="checkbox"><span>${icon('shield',17)}Private internal note — never show this message to the player</span></label><aside class="modal-note">${icon('audit',17)}Status, priority, assignment, public replies, and private notes are retained in the audit trail.</aside><footer>${button('Cancel',{action:'close-modal'})}${button('Save case',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`,{size:'large'});}
function gameModal(game={}){
  const isEdit=Boolean(game.id);
  const locked=isEdit&&!['DRAFT','SCHEDULED'].includes(game.status);
  const defaultStart=new Date(Date.now()+35*60*1000).toISOString();
  const defaultClose=new Date(Date.now()+30*60*1000).toISOString();
  const defaultOpen=new Date().toISOString();
  const lockedNote=locked?`<aside class="modal-note">${icon('shield',17)}Schedule, outcomes, and base odds are locked because betting has opened. Use the odds engine for market changes.</aside>`:'';
  return modal(isEdit?'Edit game':'Schedule a game','Game operations',`<form id="game-form" class="modal-form"><input type="hidden" name="id" value="${game.id||''}"><div class="form-grid">${field({name:'title',label:'Match title',value:game.title||'',placeholder:'Main Arena · Match 42',required:true,wide:true})}${field({name:'arena',label:'Arena',value:game.arena||'Main Arena',required:true})}${isEdit?`<div class="form-field"><span>Lifecycle status</span><div class="status-display">${badge(game.status)}<small>Use the engine controls on the match card to change state.</small></div><input type="hidden" name="status" value="${escapeHtml(game.status)}"></div>`:selectField({name:'status',label:'Initial status',value:'SCHEDULED',options:[['DRAFT','Draft'],['SCHEDULED','Scheduled']]})}${field({name:'betting_opens_at',label:'Betting opens',type:'datetime-local',value:localDateTime(game.betting_opens_at||defaultOpen),required:true,disabled:locked})}${field({name:'betting_closes_at',label:'Betting closes',type:'datetime-local',value:localDateTime(game.betting_closes_at||defaultClose),required:true,disabled:locked})}${field({name:'scheduled_at',label:'Scheduled start',type:'datetime-local',value:localDateTime(game.scheduled_at||defaultStart),required:true,disabled:locked})}${field({name:'team_a_name',label:'Red corner',value:game.team_a_name||'Red',required:true,disabled:locked})}${field({name:'team_a_odds',label:'Red odds',type:'number',value:game.team_a_odds??2.45,min:1.01,max:100,step:.01,required:true,disabled:locked})}${field({name:'draw_odds',label:'Draw odds',type:'number',value:game.draw_odds??8.75,min:1.01,max:100,step:.01,required:true,disabled:locked})}${field({name:'team_b_name',label:'Blue corner',value:game.team_b_name||'Blue',required:true,disabled:locked})}${field({name:'team_b_odds',label:'Blue odds',type:'number',value:game.team_b_odds??2.45,min:1.01,max:100,step:.01,required:true,disabled:locked})}${mediaPicker({name:'thumbnail',label:'Match thumbnail',value:game.thumbnail_url||'',kind:'image',help:'Shown on the game card and for the featured match.'})}${selectField({name:'stream_type',label:'Linked playback type',value:game.stream_type||'OFFLINE',options:['OFFLINE','VIDEO','HLS','YOUTUBE','WHEP']})}${mediaPicker({name:'stream',label:'Match video or stream',value:game.stream_url||'',kind:'video',help:'Upload a recorded MP4/WebM to play it as live, or paste a direct video/HLS/YouTube/WHEP link. An uploaded file is saved as VIDEO.'})}</div>${lockedNote}<label class="check-field"><input name="featured" type="checkbox" ${game.featured?'checked':''}><span>${icon('vip',17)}Feature this match in the player app</span></label><footer>${button('Cancel',{action:'close-modal'})}${button(isEdit?'Save game':'Create game',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`,{size:'large'});
}
function oddsModal(game){return modal(`Odds engine · ${game.title}`,'Versioned market control',`<form id="odds-form" class="modal-form"><input type="hidden" name="id" value="${game.id}"><div class="form-grid">${field({name:'team_a_odds',label:`${game.team_a_name} odds`,type:'number',value:game.team_a_odds,min:1.01,max:100,step:.01,required:true})}${field({name:'draw_odds',label:'Draw odds',type:'number',value:game.draw_odds,min:1.01,max:100,step:.01,required:true})}${field({name:'team_b_odds',label:`${game.team_b_name} odds`,type:'number',value:game.team_b_odds,min:1.01,max:100,step:.01,required:true})}${selectField({name:'market_status',label:'Market state',value:game.status==='BETTING_OPEN'?'OPEN':'SUSPENDED',options:[['OPEN','Open for quotes'],['SUSPENDED','Suspended']]})}${field({name:'reason',label:'Change reason',value:'Operator market update',required:true,wide:true})}</div><aside class="modal-note">${icon('shield',17)}Every publication creates a new immutable odds version. Existing unexpired quotes retain the odds they were issued.</aside><footer>${button('Cancel',{action:'close-modal'})}${button('Publish odds version',{type:'submit',tone:'primary',iconName:'activity'})}</footer></form>`,{size:'large'});}
function resultModal(game){return modal(`${game.result?'Confirm':'Declare'} result · ${game.title}`,'Settlement engine',`<form id="result-form" class="modal-form"><input type="hidden" name="id" value="${game.id}"><div class="form-grid">${selectField({name:'result',label:'Official outcome',value:game.result||'RED',options:[['RED',`${game.team_a_name} wins`],['DRAW','Draw / tie'],['BLUE',`${game.team_b_name} wins`],['CANCELLED','Cancel and refund all tickets']],wide:true})}</div><aside class="modal-note">${icon('alert',17)}Declaring stores the official outcome first. Settlement is a separate idempotent action so an operator can verify it before wallets change.</aside><footer>${button('Cancel',{action:'close-modal'})}${button(game.result?'Keep declared result':'Declare official result',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`);}
function streamModal(session){const game=state.games.find(item=>Number(item.id)===Number(session.game_id));return modal(`Broadcast · ${game?.title||`Match ${session.game_id}`}`,'Secure streaming session',`<section class="stream-session"><div class="stream-session__status"><span>${icon('live',24)}</span><div><small>SESSION STATUS</small><strong>${escapeHtml(session.status.replace(/_/g,' '))}</strong><p>${session.media_plane_configured?'WHIP publishing and WHEP playback are configured.':'Camera preview works now. Connect the SRS media server before going live.'}</p></div></div><div class="stream-pairing"><small>MOBILE PAIRING CODE</small><strong>${escapeHtml(session.pairing_code||'ROTATE TO VIEW')}</strong><p>Open the studio link on a mobile device, enter this one-time code, and allow camera access. The code expires ${dateTime(session.pairing_expires_at)}.</p></div><div class="stream-session__facts"><span><small>Source</small><strong>${escapeHtml(session.source_type)}</strong></span><span><small>Recording</small><strong>${session.recording_enabled?'Enabled':'Disabled'}</strong></span><span><small>Playback</small><strong>${escapeHtml(session.playback_type||'WHEP')}</strong></span></div><aside class="modal-note">${icon('shield',17)}The publisher token is stored only for this browser session and is never displayed. Creating another session revokes this one.</aside><footer>${button('Copy mobile link',{action:'copy-stream-link',iconName:'link',extra:`data-id="${escapeHtml(session.id)}"`})}${button('Open camera studio',{action:'launch-stream-studio',tone:'primary',iconName:'external',extra:`data-id="${escapeHtml(session.id)}"`})}</footer></section>`,{size:'large'});}
function bannerModal(item={}){return modal(item.id?'Edit home media':'Add home media','Player content management',`<form id="banner-form" class="modal-form"><input type="hidden" name="id" value="${item.id||''}"><div class="form-grid">${field({name:'title',label:'Section or media title',value:item.title||'',required:true,wide:true})}${field({name:'subtitle',label:'Supporting text',value:item.subtitle||'',wide:true})}${selectField({name:'placement',label:'Player placement',value:item.placement||'HOME_VIDEO',options:[['HOME_HERO','Home · main banner'],['HOME_LIVE','Home · live game card'],['HOME_VIDEO','Home · videos'],['HOME_HIGHLIGHT','Home · highlights'],['HOME_YOUTUBE','Home · YouTube highlights'],['LIVE','Live arena promotion'],['WALLET','Wallet promotion']]})}${selectField({name:'media_type',label:'Playback type',value:item.media_type||'VIDEO',options:[['VIDEO','Uploaded/direct video'],['YOUTUBE','YouTube video'],['EXTERNAL','External media page'],['IMAGE','Image/button only']]})}${mediaPicker({name:'image',label:'Thumbnail or banner artwork',value:item.image_url||'',kind:'image',help:'Upload the thumbnail or paste a secure image link.'})}${mediaPicker({name:'media',label:'Video or playback source',value:item.media_url||'',kind:'video',help:'Upload MP4/WebM, or paste a secure direct/YouTube link.'})}${field({name:'duration',label:'Displayed duration',value:item.duration||'',placeholder:'4:12',help:'Use MM:SS or HH:MM:SS.'})}${field({name:'cta_label',label:'Badge or button label',value:item.cta_label||'',placeholder:'Streaming Now'})}${field({name:'cta_route',label:'Fallback player route',value:item.cta_route||'',placeholder:'#live'})}${field({name:'starts_at',label:'Starts',type:'datetime-local',value:localDateTime(item.starts_at)})}${field({name:'ends_at',label:'Ends',type:'datetime-local',value:localDateTime(item.ends_at)})}${field({name:'sort_order',label:'Display order',type:'number',value:item.sort_order??0,min:0,max:999})}</div><label class="check-field"><input name="active" type="checkbox" ${item.id?!item.active?'':'checked':'checked'}><span>${icon('check',17)}Active and visible to players</span></label><footer>${button('Cancel',{action:'close-modal'})}${button(item.id?'Save media':'Publish media',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`,{size:'large'});}
function vipModal(item={}){return modal(item.id?'Edit VIP tier':'Create VIP tier','Loyalty management',`<form id="vip-form" class="modal-form"><input type="hidden" name="id" value="${item.id||''}"><div class="form-grid">${field({name:'name',label:'Tier name',value:item.name||'',required:true})}${field({name:'color',label:'Tier color',type:'color',value:item.color||'#F1B93D'})}${field({name:'minimum_turnover',label:'Minimum turnover (₹)',type:'number',value:item.minimum_turnover??0,min:0,max:100000000,step:1})}${field({name:'cashback_percent',label:'Cashback (%)',type:'number',value:item.cashback_percent??0,min:0,max:25,step:.01})}${field({name:'withdrawal_priority',label:'Withdrawal priority',type:'number',value:item.withdrawal_priority??0,min:0,max:20})}</div><label class="check-field"><input name="active" type="checkbox" ${item.id?!item.active?'':'checked':'checked'}><span>${icon('check',17)}Active tier</span></label><footer>${button('Cancel',{action:'close-modal'})}${button(item.id?'Save tier':'Create tier',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`);}
function userModal(user){return modal(`Manage ${user.display_name}`,'Player access',`<form id="user-form" class="modal-form"><input type="hidden" name="user_id" value="${escapeHtml(user.user_id)}"><div class="user-summary"><span>${initials(user.display_name)}</span><div><strong>${escapeHtml(user.display_name)}</strong><p>${escapeHtml(user.user_id)} · ${money(user.balance)}</p></div></div><div class="form-grid">${selectField({name:'status',label:'Account status',value:user.status,options:['ACTIVE','SUSPENDED','BLOCKED']})}${selectField({name:'vip_tier',label:'VIP tier',value:user.vip_tier,options:state.vip.map(tier=>tier.name)})}</div><aside class="modal-note">${icon('shield',17)}This does not change the user’s wallet balance. Every access change is written to the audit log.</aside><footer>${button('Cancel',{action:'close-modal'})}${button('Save account',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`);}
function accountModal(){return modal('Add receiving account','Manual payments',`<form id="payment-account-form" class="modal-form"><div class="form-grid">${field({name:'label',label:'Display label',placeholder:'RoosterRun UPI',required:true})}${selectField({name:'account_type',label:'Account type',value:'UPI',options:['UPI','BANK']})}${field({name:'account_holder',label:'Account holder',placeholder:'RoosterRun Payments',required:true})}${field({name:'upi_id',label:'UPI ID',placeholder:'name@bank'})}${field({name:'bank_name',label:'Bank name',placeholder:'State Bank of India'})}${field({name:'account_number',label:'Account number',placeholder:'123456789012'})}${field({name:'ifsc',label:'IFSC',placeholder:'SBIN0001234'})}${mediaPicker({name:'qr',label:'Payment QR image (optional)',kind:'image',help:'Upload the QR artwork or paste a secure hosted image link.'})}</div><footer>${button('Cancel',{action:'close-modal'})}${button('Add account',{type:'submit',tone:'primary',iconName:'plus'})}</footer></form>`,{size:'large'});}
function paymentModal(request){const withdrawal=request.request_type==='WITHDRAWAL';return modal(`Review ${request.reference}`,'Payment verification',`<form id="payment-decision-form" class="modal-form"><input type="hidden" name="id" value="${request.id}"><div class="decision-summary"><span>${icon(request.request_type==='DEPOSIT'?'plus':'payments',20)}</span><div><small>${escapeHtml(request.request_type)}</small><strong>${money(request.amount)}</strong><p>${escapeHtml(request.user_id)} · ${dateTime(request.created_at)}</p></div></div><div class="form-grid">${selectField({name:'decision',label:'Decision',value:'APPROVED',options:[['APPROVED','Approve'],['REJECTED','Reject']]})}${withdrawal?field({name:'payout_utr',label:'Payout UTR',placeholder:'Required unless proof is uploaded'}):''}${field({name:'admin_note',label:'Administrator note',placeholder:'Required when rejecting',wide:true})}${withdrawal?`<label class="form-field form-field--wide"><span>Payout screenshot</span><input name="payout_proof" type="file" accept="image/png,image/jpeg,image/webp"><small>Provide a payout UTR or screenshot before approval.</small></label>`:''}</div><aside class="modal-note">${icon('alert',17)}Approving changes the user wallet ledger immediately and cannot be reviewed twice.</aside><footer>${button('Cancel',{action:'close-modal'})}${button('Submit decision',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`,{size:'large'});}
function complianceModal(item){return modal(`Review ${item.display_name||item.user_id}`,'Identity and age verification',`<form id="compliance-decision-form" class="modal-form"><input type="hidden" name="user_id" value="${escapeHtml(item.user_id)}"><div class="user-summary"><span>${initials(item.display_name||item.user_id)}</span><div><strong>${escapeHtml(item.legal_name||item.display_name||item.user_id)}</strong><p>${escapeHtml(item.user_id)} · Age ${item.age??'—'} · ${escapeHtml(item.state_code||'No state')}</p></div></div><div class="private-documents">${(item.documents||[]).map(doc=>`<a href="/api/admin/compliance/documents/${doc.id}/" target="_blank" rel="noopener"><span>${icon('shield',18)}</span><div><strong>${escapeHtml(doc.document_type.replace(/_/g,' '))}</strong><small>${escapeHtml(doc.content_type)} · ${Math.ceil(Number(doc.size_bytes||0)/1024)} KB</small></div>${icon('external',16)}</a>`).join('')||'<p>No document is attached.</p>'}</div><div class="form-grid">${selectField({name:'decision',label:'Decision',value:item.status==='VERIFIED'?'VERIFIED':'REVIEW_REQUIRED',options:[['VERIFIED','Verify identity'],['REVIEW_REQUIRED','Request more information'],['REJECTED','Reject']]})}${field({name:'note',label:'Review note',value:item.review_note||'',placeholder:'Required when rejecting or requesting information',wide:true})}</div><aside class="modal-note">${icon('shield',17)}Open each private document, compare the legal name and age evidence, and record a clear reason for any non-approval.</aside><footer>${button('Cancel',{action:'close-modal'})}${button('Save verification decision',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`,{size:'large'});}
function adminModal(member={}){const editing=Boolean(member.id);const roles=(state.config.roles||[]).map(role=>[String(role.id),role.name]);return modal(editing?`Manage ${member.display_name}`:'Add administrator','Role-based access control',`<form id="admin-form" class="modal-form"><input type="hidden" name="id" value="${member.id||''}"><div class="form-grid">${field({name:'display_name',label:'Display name',value:member.display_name||'',required:true})}${editing?field({name:'username',label:'Username',value:member.username||'',disabled:true}):field({name:'username',label:'Username',placeholder:'arena.operator',required:true})}${selectField({name:'role_id',label:'Assigned role',value:String((state.config.roles||[]).find(role=>role.name===member.role)?.id||roles[0]?.[0]||''),options:roles})}${editing?'':field({name:'password',label:'Temporary password',type:'password',placeholder:'At least 10 characters with a number',required:true,wide:true})}</div>${editing?`<label class="check-field"><input name="active" type="checkbox" ${member.active?'checked':''}><span>${icon('check',17)}Account active</span></label><label class="check-field"><input name="reset_mfa" type="checkbox"><span>${icon('shield',17)}Reset MFA and recovery codes</span></label>`:''}<aside class="modal-note">${icon('shield',17)}Staff should use named accounts. Permissions are checked by the server on every request.</aside><footer>${button('Cancel',{action:'close-modal'})}${button(editing?'Save access':'Create administrator',{type:'submit',tone:'primary',iconName:'check'})}</footer></form>`);}
function mfaModal(item={}){if(item.recovery_codes)return modal('Save recovery codes','Shown only once',`<section class="stream-session"><aside class="modal-note">${icon('alert',17)}Store these codes offline. Each code can be used once if the authenticator device is unavailable.</aside><div class="mfa-recovery">${item.recovery_codes.map(code=>`<code>${escapeHtml(code)}</code>`).join('')}</div><footer>${button('I saved the codes',{action:'close-modal',tone:'primary',iconName:'check'})}</footer></section>`);return modal('Enable multi-factor authentication','Authenticator setup',`<form id="mfa-confirm-form" class="modal-form"><aside class="modal-note">${icon('shield',17)}Add the setup key to Google Authenticator, Microsoft Authenticator, 1Password, or another TOTP app.</aside><div class="stream-pairing"><small>SETUP KEY</small><strong>${escapeHtml(item.secret||'')}</strong></div><div class="form-grid">${field({name:'code',label:'Six-digit authenticator code',placeholder:'123456',required:true,wide:true})}</div><footer>${button('Cancel',{action:'close-modal'})}${button('Confirm and enable MFA',{type:'submit',tone:'primary',iconName:'shield'})}</footer></form>`);}

function applyTheme(){const theme=state.config.theme||{};const style=document.documentElement.style;if(theme.primary)style.setProperty('--gold',theme.primary);if(theme.primary_bright)style.setProperty('--gold-bright',theme.primary_bright);if(theme.background)style.setProperty('--bg',theme.background);if(theme.surface)style.setProperty('--surface',theme.surface);if(theme.text)style.setProperty('--text',theme.text);if(theme.danger)style.setProperty('--red',theme.danger);if(theme.success)style.setProperty('--green',theme.success);}
function applyOperatingModeCopy(){if(state.route!=='compliance')return;const notice=root.querySelector('.legal-lock');if(!notice)return;const mode=state.compliancePolicy?.operating_mode||'SOCIAL_PREVIEW';const copyByMode={REAL_MONEY:['Real-money mode is active','Live wallets, deposits, withdrawals, betting, and settlement move real funds. Every payment must be verified against bank/UPI evidence before approval.'],APPROVAL_DEMO:['Approval demo is active','Registration, verification, demo betting, settlement, deposits, and withdrawals can be presented end to end. All balances and transfers are demonstrative; no real funds are accepted or paid.'],SOCIAL_PREVIEW:['Social-preview mode is active','Real-money operation is disabled. Set ROOSTERRUN_OPERATING_MODE=REAL_MONEY on the server to enable live wallets.']};const [titleText,copyText]=copyByMode[mode]||copyByMode.SOCIAL_PREVIEW;const title=notice.querySelector('strong');const copy=notice.querySelector('p');if(title)title.textContent=titleText;if(copy)copy.textContent=copyText;}
function render(){if(state.authRequired){root.innerHTML=renderAuth();return;}root.innerHTML=shell(view());applyTheme();applyOperatingModeCopy();}
async function refreshAll(){state.loading=true;state.error='';render();try{const session=await api.session();state.admin=session.admin;const tasks=[api.overview().then(value=>state.overview=value),api.config().then(value=>state.config=value)];if(hasPermission('operations'))tasks.push(api.operations().then(value=>state.operations=value));if(hasPermission('intelligence'))tasks.push(api.intelligence().then(value=>state.intelligence=value),api.intelligenceAlerts().then(value=>state.intelligenceAlerts=value));if(hasPermission('support'))tasks.push(api.support().then(value=>state.support=value));if(hasPermission('users'))tasks.push(api.users().then(value=>state.users=value.results||[]),api.vip().then(value=>state.vip=value.results||[]));else if(hasPermission('vip'))tasks.push(api.vip().then(value=>state.vip=value.results||[]));if(hasPermission('games'))tasks.push(api.games().then(value=>state.games=value.results||[]),api.streams().then(value=>state.streams=value.results||[]),api.streamHealth().then(value=>state.streamHealth=value),api.risk().then(value=>state.risk=value),api.chinaFeed().then(value=>state.chinaFeed=value));if(hasPermission('payments'))tasks.push(api.paymentAccounts().then(value=>state.paymentAccounts=value.results||[]),api.paymentRequests().then(value=>state.paymentRequests=value.results||[]));if(hasPermission('compliance'))tasks.push(api.compliance().then(value=>state.compliance=value.results||[]),api.compliancePolicy().then(value=>state.compliancePolicy=value));if(hasPermission('banners'))tasks.push(api.banners().then(value=>state.banners=value.results||[]));if(hasPermission('team'))tasks.push(api.team().then(value=>state.team=value.results||[]));if(hasPermission('audit'))tasks.push(api.audit().then(value=>state.audit=value.results||[]));await Promise.all(tasks);if(!hasPermission(routePermissions[state.route])){state.route='overview';window.history.replaceState(null,'','#overview');}Object.assign(state,{loading:false,authRequired:false,authError:''});}catch(error){if(error instanceof AdminApiError&&(error.status===401||error.status===403)){state.authRequired=true;state.loading=false;state.admin=null;}else{state.error=error.message;state.loading=false;}}render();}
async function refreshModules(...modules){const jobs={overview:async()=>state.overview=await api.overview(),operations:async()=>state.operations=await api.operations(),intelligence:async()=>{state.intelligence=await api.intelligence();state.intelligenceAlerts=await api.intelligenceAlerts();},support:async()=>state.support=await api.support(),users:async()=>state.users=(await api.users()).results||[],games:async()=>state.games=(await api.games()).results||[],chinaFeed:async()=>state.chinaFeed=await api.chinaFeed(),streams:async()=>{state.streams=(await api.streams()).results||[];state.streamHealth=await api.streamHealth();},payments:async()=>{state.paymentAccounts=(await api.paymentAccounts()).results||[];state.paymentRequests=(await api.paymentRequests()).results||[];},compliance:async()=>{state.compliance=(await api.compliance()).results||[];state.compliancePolicy=await api.compliancePolicy();},banners:async()=>state.banners=(await api.banners()).results||[],vip:async()=>state.vip=(await api.vip()).results||[],config:async()=>state.config=await api.config(),risk:async()=>state.risk=await api.risk(),team:async()=>state.team=(await api.team()).results||[],audit:async()=>state.audit=(await api.audit()).results||[]};await Promise.all(modules.map(name=>jobs[name]?.()));}
function toast(message,tone='success'){state.toast={message,tone};render();window.setTimeout(()=>{state.toast=null;render();},3200);}
function openModal(type,item={}){state.modal={type,item};render();}function closeModal(){state.modal=null;render();}
async function imageData(file,required=false){if(!file){if(required)throw new Error('Select an image.');return '';}if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Use a PNG, JPG, or WebP image.');if(file.size>2_500_000)throw new Error('The image must be smaller than 2.5 MB.');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('The image could not be read.'));reader.readAsDataURL(file);});}
async function mediaValue(form,data,name,kind){const file=form.elements[`${name}_file`]?.files?.[0];if(file)return (await api.uploadAsset(file,kind)).url;return String(data.get(`${name}_url`)||'').trim();}
function isoValue(value){const date=new Date(String(value||''));if(Number.isNaN(date.getTime()))throw new Error('Enter a valid schedule date and time.');return date.toISOString();}

document.addEventListener('click',async event=>{
  const routeControl=event.target.closest('[data-route]');
  if(routeControl){event.preventDefault();window.location.hash=routeControl.dataset.route;state.mobileOpen=false;return;}
  const control=event.target.closest('[data-action]');if(!control)return;
  const action=control.dataset.action;
  if(action==='open-player-live'){window.open('/play/#live','_blank','noopener');}
  else if(action==='publish-media'){
    event.preventDefault();const form=control.closest('form');const data=new FormData(form);const id=Number(data.get('id'))||null;state.busy=true;control.disabled=true;
    try{const payload=Object.fromEntries(data.entries());delete payload.id;delete payload.image_file;delete payload.image_url;delete payload.media_file;delete payload.media_url;payload.image_url=await mediaValue(form,data,'image','IMAGE');const uploadedVideo=Boolean(form.elements.media_file?.files?.[0]);payload.media_url=await mediaValue(form,data,'media','VIDEO');if(uploadedVideo)payload.media_type='VIDEO';for(const key of ['starts_at','ends_at']){const value=data.get(key);payload[key]=value?isoValue(value):'';}payload.active=data.get('active')==='on';await api.saveBanner(id,payload);closeModal();await refreshModules('banners','overview','audit');toast(id?'Home media updated.':'Home media published.');}catch(error){toast(error.message||'Home media could not be saved.','error');}finally{state.busy=false;}
  }
  else if(action==='submit-form'){event.preventDefault();const form=control.closest('form');if(form)await submitAdminForm(form);}
  else if(action==='open-menu'){state.mobileOpen=true;render();}
  else if(action==='close-menu'){state.mobileOpen=false;render();}
  else if(action==='close-modal'){if(control.classList.contains('modal-backdrop')&&event.target!==control)return;closeModal();}
  else if(action==='retry-load')refreshAll();
  else if(action==='new-game')openModal('game');
  else if(action==='china-poll'){try{const result=await api.pollChinaFeed();await refreshModules('chinaFeed','games','audit');toast(result.error?`Feed error: ${result.error}`:`Polled upstream match ${result.ref_id||''}${result.actions?.length?` · ${result.actions.join(', ')}`:''}`,result.error?'error':'success');}catch(error){toast(error.message,'error');}}
  else if(action==='china-recover'){try{const result=await api.recoverChinaFeed();await refreshModules('chinaFeed','games','audit');toast(`Recovered ${result.recovered} result${result.recovered===1?'':'s'} from upstream history.`);}catch(error){toast(error.message,'error');}}
  else if(action==='edit-game')openModal('game',state.games.find(item=>String(item.id)===control.dataset.id));
  else if(action==='edit-odds')openModal('odds',state.games.find(item=>String(item.id)===control.dataset.id));
  else if(action==='declare-result')openModal('result',state.games.find(item=>String(item.id)===control.dataset.id));
  else if(action==='create-stream'){
    try{const game=state.games.find(item=>String(item.id)===control.dataset.id);const session=await api.createStreamSession(control.dataset.id,{source_type:'CAMERA',client_label:`${game?.arena||'Arena'} camera`,recording_enabled:true});state.streams=[session,...state.streams.filter(item=>Number(item.game_id)!==Number(session.game_id))];openModal('stream',session);}catch(error){toast(error.message,'error');}
  }
  else if(action==='open-stream'){
    try{const session=await api.rotateStreamCredentials(control.dataset.id);state.streams=state.streams.map(item=>item.id===session.id?session:item);openModal('stream',session);}catch(error){toast(error.message,'error');}
  }
  else if(action==='launch-stream-studio'){
    const session=state.modal?.item;if(!session?.publisher_token){toast('Rotate the broadcast credentials first.','error');return;}
    sessionStorage.setItem(`roosterrun_broadcast_${session.id}`,session.publisher_token);
    const studio=window.open(session.studio_url||`/broadcast/?session=${encodeURIComponent(session.id)}`,'_blank');
    if(!studio){toast('Allow pop-ups to open the camera studio.','error');return;}
    const message={type:'roosterrun-broadcast-token',sessionId:session.id,token:session.publisher_token};let attempts=0;
    const relay=window.setInterval(()=>{attempts+=1;if(studio.closed||attempts>20){window.clearInterval(relay);return;}studio.postMessage(message,window.location.origin);},250);
    closeModal();toast('Broadcast studio opened.');
  }
  else if(action==='copy-stream-link'){
    const link=`${window.location.origin}/broadcast/?session=${encodeURIComponent(control.dataset.id)}`;
    try{await navigator.clipboard.writeText(link);toast('Mobile studio link copied. Share the pairing code separately.');}catch{toast(link,'error');}
  }
  else if(action==='stop-stream'){
    if(!window.confirm('End this live broadcast session now?'))return;
    try{await api.stopStreamSession(control.dataset.id);await refreshModules('streams','games','overview','audit');toast('Broadcast session ended.');}catch(error){toast(error.message,'error');}
  }
  else if(action==='transition-game'){try{await api.transitionGame(control.dataset.id,control.dataset.status,`Operator advanced match to ${control.dataset.status}`);await refreshModules('games','overview','audit');toast(`Match moved to ${control.dataset.status.replace(/_/g,' ').toLowerCase()}.`);}catch(error){toast(error.message,'error');}}
  else if(action==='settle-game'){if(!window.confirm('Settle every pending ticket and update player wallets now?'))return;try{const summary=await api.settleGame(control.dataset.id);await refreshModules('games','users','overview','audit');toast(`Settlement complete: ${summary.bets} tickets processed.`);}catch(error){toast(error.message,'error');}}
  else if(action==='new-banner')openModal('banner');
  else if(action==='edit-banner')openModal('banner',state.banners.find(item=>String(item.id)===control.dataset.id));
  else if(action==='new-vip')openModal('vip');
  else if(action==='edit-vip')openModal('vip',state.vip.find(item=>String(item.id)===control.dataset.id));
  else if(action==='new-admin')openModal('admin');
  else if(action==='edit-admin')openModal('admin',state.team.find(item=>String(item.id)===control.dataset.id));
  else if(action==='enroll-mfa'){try{openModal('mfa',await api.enrollMfa());}catch(error){toast(error.message,'error');}}
  else if(action==='cancel-admin-mfa'){state.authStep='credentials';state.authChallenge='';state.authError='';render();}
  else if(action==='edit-user')openModal('user',state.users.find(item=>item.user_id===control.dataset.id));
  else if(action==='review-support')openModal('support',state.support.results.find(item=>String(item.id)===control.dataset.id));
  else if(action==='review-intelligence')openModal('intelligence',state.intelligenceAlerts.results.find(item=>String(item.id)===control.dataset.id));
  else if(action==='run-intelligence-scan'){state.busy=true;render();try{const scan=await api.scanIntelligence();await refreshModules('intelligence','operations','audit');toast(`Detection completed: ${scan.new_alert_count} new alert${scan.new_alert_count===1?'':'s'}.`);}catch(error){toast(error.message,'error');}finally{state.busy=false;render();}}
  else if(action==='export-intelligence'){state.busy=true;render();try{const result=await api.exportIntelligence();toast(`${result.filename} was exported securely.`);}catch(error){toast(error.message,'error');}finally{state.busy=false;render();}}
  else if(action==='new-payment-account')openModal('account');
  else if(action==='review-payment')openModal('payment',state.paymentRequests.find(item=>String(item.id)===control.dataset.id));
  else if(action==='review-compliance')openModal('compliance',state.compliance.find(item=>item.user_id===control.dataset.id));
  else if(action==='toggle-payment-account'){try{await api.togglePaymentAccount(control.dataset.id);await refreshModules('payments','overview','audit');toast('Payment account availability updated.');}catch(error){toast(error.message,'error');}}
  else if(action==='run-reconciliation'){if(!window.confirm('Run a read-only reconciliation across payment ledgers, bet holds, settlements, balances, and database integrity?'))return;state.busy=true;render();try{const run=await api.runReconciliation();await refreshModules('operations','audit');toast(`Reconciliation ${run.status.toLowerCase()}: ${run.findings.length} finding(s).`,run.status==='PASS'?'success':'error');}catch(error){toast(error.message,'error');}finally{state.busy=false;render();}}
  else if(action==='create-backup'){state.busy=true;render();try{const backup=await api.createBackup();await refreshModules('operations','audit');toast(`${backup.reference} was created and verified.`);}catch(error){toast(error.message,'error');}finally{state.busy=false;render();}}
  else if(action==='ack-incident'){try{await api.updateIncident(control.dataset.id,{status:'ACKNOWLEDGED',note:''});await refreshModules('operations','audit');toast('Incident acknowledged.');}catch(error){toast(error.message,'error');}}
  else if(action==='resolve-incident'){const note=window.prompt('Describe the verified resolution:','');if(note===null)return;try{await api.updateIncident(control.dataset.id,{status:'RESOLVED',note});await refreshModules('operations','audit');toast('Incident resolved with an audit note.');}catch(error){toast(error.message,'error');}}
  else if(action==='sign-out'){try{if(!localPreview)await api.logout();}catch{/* Expired sessions still return to the sign-in screen. */}state.authRequired=!localPreview;state.admin=null;state.authStep='credentials';render();}
});
document.addEventListener('input',event=>{if(event.target.matches('[data-table-search]')){const query=event.target.value.trim().toLowerCase();document.querySelectorAll('[data-search-row]').forEach(row=>row.hidden=query&&!row.dataset.searchRow.includes(query));}if(event.target.matches('.color-grid input[type="color"]')){const text=event.target.parentElement.querySelector('input:not([type="color"])');if(text)text.value=event.target.value.toUpperCase();}if(event.target.matches('.color-grid input:not([type="color"])')){const color=event.target.parentElement.querySelector('input[type="color"]');if(color&&/^#[0-9a-f]{6}$/i.test(event.target.value))color.value=event.target.value;}});
async function submitAdminForm(form){
  const formId=form.getAttribute('id')||'';
  const data=new FormData(form);
  state.busy=true;
  try{
    if(formId==='admin-auth-form'){
      state.authError='';
      try{const result=state.authStep==='mfa'?await api.verifyMfa({challenge_id:state.authChallenge,code:String(data.get('code')||'')}):await api.login({username:String(data.get('username')||''),password:String(data.get('password')||'')});if(result.mfa_required){state.authStep='mfa';state.authChallenge=result.challenge_id;state.busy=false;render();return;}state.admin=result.admin;state.authRequired=false;state.authStep='credentials';state.authChallenge='';await refreshAll();}catch(error){state.authError=error.message;state.busy=false;render();}return;
    }
    if(formId==='game-form'){
      const id=Number(data.get('id'))||null;
      const payload=Object.fromEntries(data.entries());
      delete payload.id;delete payload.thumbnail_file;delete payload.stream_file;
      payload.thumbnail_url=await mediaValue(form,data,'thumbnail','IMAGE');
      const uploadedVideo=Boolean(form.elements.stream_file?.files?.[0]);
      payload.stream_url=await mediaValue(form,data,'stream','VIDEO');
      if(uploadedVideo)payload.stream_type='VIDEO';
      for(const key of ['betting_opens_at','betting_closes_at','scheduled_at']){const value=data.get(key);if(value)payload[key]=isoValue(value);}
      payload.featured=data.get('featured')==='on';
      await api.saveGame(id,payload);closeModal();await refreshModules('games','overview','audit');toast(id?'Game updated.':'Game created.');
    }else if(formId==='support-case-form'){
      const id=Number(data.get('id'));const message=String(data.get('new_message')||'').trim();const internal=data.get('internal')==='on';if(message)await api.replySupport(id,{message,internal});const status=message&&!internal?'WAITING_FOR_PLAYER':data.get('status');await api.updateSupport(id,{status,priority:data.get('priority'),assigned_admin:data.get('assigned_admin'),resolution_summary:data.get('resolution_summary')});closeModal();await refreshModules('support','operations','audit');toast(message&&!internal?'Reply sent and case is waiting for the player.':'Support case updated.');
    }else if(formId==='intelligence-alert-form'){
      await api.updateIntelligenceAlert(Number(data.get('id')),{status:data.get('status'),assigned_admin:data.get('assigned_admin'),resolution_note:data.get('resolution_note')});closeModal();await refreshModules('intelligence','audit');toast('Investigation decision recorded.');
    }else if(formId==='intelligence-policy-form'){
      const payload={};['large_withdrawal_rupees','rapid_cashout_minutes','rapid_cashout_percent','rejected_payments_24h','rejected_risk_checks_15m','betting_velocity_5m','betting_velocity_stake_rupees','shared_beneficiary_users'].forEach(key=>payload[key]=Number(data.get(key)));await api.saveIntelligencePolicy(payload);await refreshModules('intelligence','audit');toast('Detection policy saved.');
    }else if(formId==='odds-form'){
      const id=Number(data.get('id'));await api.saveOdds(id,{team_a_odds:data.get('team_a_odds'),draw_odds:data.get('draw_odds'),team_b_odds:data.get('team_b_odds'),market_status:data.get('market_status'),reason:data.get('reason')});closeModal();await refreshModules('games','audit');toast('A new odds version was published.');
    }else if(formId==='result-form'){
      const id=Number(data.get('id'));await api.declareResult(id,data.get('result'));closeModal();await refreshModules('games','overview','audit');toast('Official result declared. Verify it, then run settlement.');
    }else if(formId==='banner-form'){
      const id=Number(data.get('id'))||null;
      const payload=Object.fromEntries(data.entries());
      delete payload.id;delete payload.image_file;delete payload.image_url;delete payload.media_file;delete payload.media_url;
      payload.image_url=await mediaValue(form,data,'image','IMAGE');
      const uploadedVideo=Boolean(form.elements.media_file?.files?.[0]);
      payload.media_url=await mediaValue(form,data,'media','VIDEO');
      if(uploadedVideo)payload.media_type='VIDEO';
      for(const key of ['starts_at','ends_at']){const value=data.get(key);payload[key]=value?isoValue(value):'';}
      payload.active=data.get('active')==='on';
      await api.saveBanner(id,payload);closeModal();await refreshModules('banners','overview','audit');toast(id?'Home media updated.':'Home media published.');
    }else if(formId==='vip-form'){
      const id=Number(data.get('id'))||null;const payload=Object.fromEntries(data.entries());delete payload.id;payload.active=data.get('active')==='on';await api.saveVip(id,payload);closeModal();await refreshModules('vip','users','overview','audit');toast(id?'VIP tier updated.':'VIP tier created.');
    }else if(formId==='user-form'){
      await api.updateUser(String(data.get('user_id')),{status:data.get('status'),vip_tier:data.get('vip_tier')});closeModal();await refreshModules('users','overview','audit');toast('User access updated.');
    }else if(formId==='admin-form'){
      const id=Number(data.get('id'))||null;const payload={display_name:data.get('display_name'),role_id:Number(data.get('role_id'))};if(id){payload.active=data.get('active')==='on';payload.reset_mfa=data.get('reset_mfa')==='on';await api.updateAdmin(id,payload);}else{payload.username=data.get('username');payload.password=data.get('password');await api.createAdmin(payload);}closeModal();await refreshModules('team','audit');toast(id?'Administrator access updated.':'Administrator account created.');
    }else if(formId==='mfa-confirm-form'){
      const result=await api.confirmMfa(String(data.get('code')||''));state.admin={...state.admin,mfa_enabled:true};state.modal={type:'mfa',item:result};await refreshModules('team','audit');render();return;
    }else if(formId==='payment-account-form'){
      const payload=Object.fromEntries(data.entries());delete payload.qr_file;payload.qr_url=await mediaValue(form,data,'qr','IMAGE');await api.addPaymentAccount(payload);closeModal();await refreshModules('payments','audit');toast('Receiving account added.');
    }else if(formId==='payment-decision-form'){
      const id=Number(data.get('id'));const payload={decision:data.get('decision'),admin_note:data.get('admin_note'),payout_utr:data.get('payout_utr')||'',payout_proof_data_url:await imageData(form.elements.payout_proof?.files[0],false)};await api.decidePayment(id,payload);closeModal();await refreshModules('payments','users','overview','audit');toast('Payment decision recorded.');
    }else if(formId==='compliance-decision-form'){
      await api.decideCompliance(String(data.get('user_id')),{decision:data.get('decision'),note:data.get('note')});closeModal();await refreshModules('compliance','audit');toast('Verification decision recorded.');
    }else if(formId==='compliance-policy-form'){
      const blocked=String(data.get('blocked_state_codes')||'').split(',').map(value=>value.trim().toUpperCase()).filter(Boolean);await api.saveCompliancePolicy({minimum_age:Number(data.get('minimum_age')),limit_increase_delay_hours:Number(data.get('limit_increase_delay_hours')),document_retention_days:Number(data.get('document_retention_days')),blocked_state_codes:blocked,legal_notice:data.get('legal_notice'),kyc_required_for_betting:data.get('kyc_required_for_betting')==='on',kyc_required_for_deposit:data.get('kyc_required_for_deposit')==='on',kyc_required_for_withdrawal:data.get('kyc_required_for_withdrawal')==='on'});await refreshModules('compliance','audit');toast('Safeguard policy saved.');
    }else if(formId==='appearance-form'){
      const brand={...(state.config.brand||{}),site_name:data.get('site_name'),tagline:data.get('tagline'),logo_url:await mediaValue(form,data,'logo','IMAGE')};const theme={};['primary','primary_bright','background','surface','text','danger','success'].forEach(key=>theme[key]=String(data.get(`${key}_text`)||data.get(key)).toUpperCase());await api.saveConfig({brand,theme});await refreshModules('config','audit');toast('Global appearance saved.');
    }else if(formId==='social-form'){
      const links=(state.config.social||[]).map((link,index)=>({platform:data.get(`platform_${index}`),url:data.get(`url_${index}`),active:data.get(`active_${index}`)==='on'}));await api.saveSocial(links);await refreshModules('config','audit');toast('Social links saved.');
    }else if(formId==='china-feed-form'){
      const payload={enabled:data.get('enabled')==='on',feature_current_match:data.get('feature_current_match')==='on'};['info_url','history_url','stream_url_override','title_prefix','arena','team_a_name','team_b_name'].forEach(key=>payload[key]=String(data.get(key)||'').trim());['team_a_odds','draw_odds','team_b_odds'].forEach(key=>payload[key]=Number(data.get(key)));['poll_seconds','suspend_after_failures'].forEach(key=>payload[key]=Number(data.get(key)));await api.saveChinaFeed(payload);await refreshModules('chinaFeed','games','audit');toast('China 24/7 feed settings saved.');
    }else if(formId==='settings-form'){
      const general={timezone:data.get('timezone'),currency:data.get('currency'),language:data.get('language'),maintenance_mode:data.get('maintenance_mode')==='on'};const responsible={minimum_age:Number(data.get('minimum_age')),deposit_minimum:Number(data.get('deposit_minimum')),deposit_maximum:Number(data.get('deposit_maximum')),withdrawal_minimum:Number(data.get('withdrawal_minimum')),withdrawal_maximum:Number(data.get('withdrawal_maximum'))};const notifications={payment_alerts:data.get('payment_alerts')==='on',game_alerts:data.get('game_alerts')==='on',security_alerts:data.get('security_alerts')==='on'};const risk={minimum_stake:Number(data.get('risk_minimum_stake')),maximum_stake:Number(data.get('risk_maximum_stake')),maximum_user_exposure:Number(data.get('risk_maximum_user_exposure')),maximum_match_pool:Number(data.get('risk_maximum_match_pool')),maximum_outcome_liability:Number(data.get('risk_maximum_outcome_liability')),maximum_bets_per_minute:Number(data.get('risk_maximum_bets_per_minute')),quote_ttl_seconds:Number(data.get('risk_quote_ttl_seconds'))};await Promise.all([api.saveConfig({general,responsible,notifications}),api.saveRisk(risk)]);await refreshModules('config','risk','audit');toast('Platform and risk settings saved.');
    }
  }catch(error){toast(error.message||'The change could not be saved.','error');}
  finally{state.busy=false;}
}
document.addEventListener('submit',event=>{event.preventDefault();submitAdminForm(event.target);});
const routeModules={overview:['overview'],operations:['operations'],intelligence:['intelligence'],support:['support'],users:['users'],games:['games','chinaFeed','streams','risk'],payments:['payments'],compliance:['compliance'],banners:['banners'],vip:['vip'],appearance:['config'],social:['config'],settings:['config'],team:['team'],audit:['audit']};
window.addEventListener('hashchange',()=>{state.route=routeFromHash();state.modal=null;state.mobileOpen=false;render();if(state.admin)refreshModules(...(routeModules[state.route]||[])).then(render).catch(()=>{});});
refreshAll();
